/** Original VNDRLY/U knowledge instruction. No issuer endorsement is represented.
 * Scenarios are synthetic training problems, never field operating instructions. */
const sources = {
 rig: ['https://iadc.org/accreditation/rigpass/','https://www.osha.gov/etools/oil-and-gas'],
 care: ['https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support','https://www.redcross.org/take-a-class/cpr/performing-cpr/cpr-steps','https://www.redcross.org/take-a-class/aed/using-an-aed/aed-steps','https://cpr.heart.org/en/resuscitation-science/2024-first-aid-guidelines'],
 haz: ['https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.120','https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.120AppE'],
 crane: ['https://www.nccco.org/nccco/certifications/mobile-crane-operator/certification-overview','https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.1427','https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.1417','https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.1402','https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.1408'],
 cdl: ['https://www.fmcsa.dot.gov/registration/commercial-drivers-license/entry-level-driver-training-eldt','https://tpr.fmcsa.dot.gov/content/Resources/ELDT-Curriculum-Summary_508.pdf','https://www.fmcsa.dot.gov/regulations/hours-service/summary-hours-service-regulations'],
 twic: ['https://www.tsa.gov/for-industry/twic','https://www.tsa.gov/for-industry/twic_faq','https://www.dhs.gov/xlibrary/assets/privacy/privacy_pia_twic09.pdf','https://files.gao.gov/reports/GAO-26-107521/index.html','https://public-inspection.federalregister.gov/2016-19383.pdf?1471869926='],
 well: ['https://iadc.org/accreditation/wellsharp/','https://www.iwcf.org/programmes/drilling-well-control-programme/','https://www.osha.gov/etools/oil-and-gas','https://iadc.org/wp-content/uploads/2015/06/IADC-Bullhead_FIELD-012214.pdf'],
 offshore: ['https://opito.com/standards-and-qualifications/industry-standards-library','https://opito.com/standards-and-qualifications/industry-standards-library/basic-offshore-safety-induction-and-emergency-training-bosiet-with-emergency-breathing-system-ebs-digital-delivery','https://opito.com/centre-network'],
 mewp: ['https://www.ipaf.org/en-us/training-courses/mewp-operator-training','https://www.osha.gov/etools/scaffolding/aerial-lifts','https://www.osha.gov/sites/default/files/publications/AERIAL_LIFTS.pdf'],
 rope: ['https://irata.org/page/training-requirements','https://irata.org/uploads/documents/International_Code_of_Practice_%28ICOP%29_-_English_TC-102ENG.pdf','https://irata.org/neuigkeiten/article/new-icop-annex-R/'],
 marine: ['https://www.dco.uscg.mil/nmc/STCW/','https://www.ecfr.gov/current/title-46/chapter-I/subchapter-B/part-11/subpart-C/section-11.302','https://www.dco.uscg.mil/Portals/9/DCO%20Documents/5p/5ps/NVIC/2025/NVIC%2001-26%20Guidelines%20for%20Coast%20Guard%20Approved%20Training%202JUN2026.pdf?ver=kCMwTe4P2oaqdGMA_cgPIA%3D%3D'],
};
// The four sections are instructional text, a solved problem, a transfer exercise,
// and observable evaluator criteria. No completion is inferred from attendance.
const L=(title,teach,scenario,practice,questions)=>({title,teach,scenario,practice,questions});
const Q=(prompt,answer,a,b,c,explanation)=>({prompt,answer,distractors:[a,b,c],explanation});
const programs={};
function add(id,group,route,rows){
 const lessons=rows.map((r,i)=>({id:`${id}_technical_${i+1}`,title:r.title,body:`${r.teach}\n\nWorked case\n${r.scenario}\n\nApplication and instructor observation\n${r.practice}\n\nAssessment record\nExplain your reasoning before seeing the answer key. The evaluator records the assumptions you used, the evidence you selected, the consequence of an incorrect decision, and any correction after feedback. A correct guess is not demonstrated understanding. For a practical session, identify the actual equipment, location, instructor and observed actions separately from this written exercise. ${i===rows.length-1?route:'A written scenario demonstrates knowledge only; physical performance must be observed in the appropriate controlled training setting.'}`,links:sources[group].map(url=>({label:'Official reference',url})),fileIds:[]}));
 const checks=rows.flatMap((r,i)=>r.questions.map((q,j)=>({id:`${id}_technical_${i+1}_check_${j+1}`,lessonId:lessons[i].id,...q})));
 programs[id]={lessons,checks,review:{sources:sources[group],coverage:rows.map(r=>r.title),limitations:route,reviewedAt:'2026-11-07',assessmentScope:'Original VNDRLY/U knowledge and scenario assessment. Practical rubric supplied for separate supervised delivery; no practical result or external credential implied.'}};
}

add('OG50','marine','This original VNDRLY marine-safety knowledge course does not issue STCW Basic Training or a mariner endorsement. Use the current Coast Guard-approved initial/refresher/revalidation route, required practical demonstrations and applicable sea-service/proficiency evidence. BOSIET is not automatically interchangeable. Verify current 2026 PSSR violence/harassment requirements with the approved provider.',[
 L('Shipboard emergencies and personal survival techniques',
 'A ship is a moving workplace with limited external assistance. Personal survival begins with familiarization: alarms, muster duties, escape routes, lifejackets, immersion protection and assigned survival craft. The master and emergency organization direct abandonment; a general alarm is not permission for each person to choose an independent escape method. Understand how to report and remain accounted for. Survival equipment has specified fitting and operating instructions. Lifejacket use, water entry, survival-craft boarding and recovery are physical competencies, not facts proved by a written quiz. Cold water, sea state, injury and clothing affect performance. A vessel-specific briefing connects training to the actual equipment and station. Keep escape routes clear and identify alternatives before an emergency.',
 'A new crew member has prior survival training but does not know the assigned muster station on this vessel. During a drill the person heads to a familiar-looking craft on the wrong side. The gap is vessel familiarization, not necessarily the old course. The crew member learns the station, alternate routes and accountability process, then demonstrates the route in the next controlled drill.',
 'Use a fictional ship plan to identify alarms, station, primary/alternative escape and reporting. The evaluator then conducts an actual vessel familiarization walk where authorized. Approved practical survival demonstrations use the provider equipment and safety arrangements. Do not assign unsupervised water entry or assume a swimming certificate establishes survival-craft competence.',[
 Q('Does prior survival training remove vessel familiarization?','No; stations and equipment differ.','Yes on all ships.','Only for short voyages.','Only if the vessel is small.','General competence must be connected to the actual vessel.'),
 Q('Does a general alarm authorize independent abandonment?','No; follow the emergency organization and instructions.','Yes automatically.','Only at night.','Only for contractors.','Muster and abandonment are distinct controlled actions.'),
 Q('What establishes survival-craft boarding skill?','Observed approved practical performance.','A written description alone.','Attendance without participation.','A photo near a liferaft.','Physical competence requires demonstration.')]),
 L('Fire prevention, detection and shipboard response',
 'Shipboard fire prevention connects ignition sources, fuel storage, housekeeping, electrical condition, hot work and ventilation control. A fire in one compartment can threaten adjacent spaces through heat and smoke. Discovering fire requires prompt alarm and accurate location reporting. Fire doors and boundaries support containment when used as intended; wedging them open can defeat a protective function. Portable extinguishers, fixed systems and breathing apparatus have different applications and training requirements. Crew members act within assigned emergency duties, preserving escape and communication. A basic-training lesson does not authorize untrained entry into smoke or operation of every fixed system. Firefighting practicals need approved facilities, instructors and safety controls; the physical demands and equipment limitations must be experienced safely under supervision.',
 'A store-room fire is reported only as aft, leaving responders uncertain about deck and compartment. The corrected report identifies the exact location, observed smoke, people at risk and known hazards. The team also discovers a fire door had been wedged open for convenience. The review addresses location communication and restoration of the boundary rather than treating extinguisher availability as the only control.',
 'On a ship plan, identify compartment boundaries and a safe reporting route. With inert equipment, classify extinguisher functions using the provider instruction and explain when withdrawal is required. Approved practical assessment observes the required fire skills separately. The evaluator rejects answers that assume a small flame means safe breathable air or that any mask permits smoke entry.',[
 Q('Why does a wedged fire door matter?','It can defeat a containment boundary.','It only affects appearance.','It improves every evacuation.','It replaces ventilation control.','Fire boundaries help limit heat and smoke spread.'),
 Q('What improves the report fire aft?','Exact deck/compartment and observed conditions.','Only louder speech.','A guessed cause alone.','The vessel age.','Responders need a precise location and credible observations.'),
 Q('Does basic knowledge authorize smoke entry?','No; assigned capability and suitable equipment are required.','Yes with any mask.','Only for a brief time.','Only if a hose is nearby.','Respiratory and firefighting tasks require specific competence.')]),
 L('Elementary first aid at sea',
 'Elementary first aid recognizes urgent conditions, starts appropriate trained care and connects the casualty to the vessel medical response. Scene safety includes moving machinery, electricity, toxic atmosphere and unstable decks. An unresponsive person with absent or abnormal breathing needs immediate emergency activation and CPR/AED action within current training. Severe bleeding needs prompt control and escalation. Record important times, observations, care and changes. At sea, medical advice may be remote; clear factual communication is therefore especially important. Do not substitute a confident diagnosis for observed signs. Avoid unnecessary movement after major trauma unless needed for immediate safety or lifesaving care. The first aider must understand the actual equipment location and the vessel call route before an incident.',
 'A crew member is injured near moving deck machinery. The initial response controls access to the hazard and activates help; a second casualty would worsen the emergency. Once access is safe, the trained first aider reports consciousness, breathing, bleeding and care. The shore medical adviser receives a structured account rather than an unsupported statement that the injury is minor.',
 'Run a manikin-based scene assessment and remote handover drill. Use the current approved elementary-first-aid curriculum for physical CPR/AED and other skills. The evaluator scores hazard recognition, activation, observed care and concise communication. This written course does not establish medication, advanced care or hazardous rescue competence.',[
 Q('What should remote medical advice receive?','Observed condition, times, care and changes.','Only a speculative diagnosis.','Only the vessel destination.','An assurance that nothing is serious.','Reliable information supports decisions when the clinician is remote.'),
 Q('What comes before access near moving machinery?','Control of the rescue exposure and emergency activation.','Immediate uncontrolled entry.','A course-certificate photograph.','Waiting for paperwork.','Rescuers must not become additional casualties.'),
 Q('Does elementary first-aid knowledge qualify advanced treatment?','No.','Yes if help is far away.','Only on international voyages.','Only for senior crew.','Distance does not create untrained clinical competence.')]),
 L('Personal safety, social responsibilities and respectful conduct',
 'Personal safety and social responsibilities connect individual conduct to a functioning crew. Follow emergency procedures, use safe work practices, prevent pollution and communicate effectively across language and cultural differences. Fatigue, workload and poor communication can undermine judgment even among skilled people. Respectful conduct is a safety issue: violence, harassment, sexual harassment, bullying and sexual assault can harm people and suppress reporting. Current STCW-related PSSR delivery must account for the applicable updated prevention and response requirements. Workers should know reporting channels, immediate-support arrangements and protections against retaliation. Describe conduct factually, protect privacy and avoid pressuring a person to disclose details publicly. Bystanders can seek help and interrupt safely within their role; they should not conduct an amateur investigation or promise absolute confidentiality they cannot control.',
 'A junior crew member is repeatedly humiliated and threatened when asking safety questions. Others call it normal shipboard humor. The behavior undermines both welfare and hazard reporting. A responsible response uses the vessel reporting and support process, records facts appropriately and addresses immediate safety. The learner must distinguish a respectful performance correction from intimidation and retaliation.',
 'Discuss fictional cases involving fatigue, unclear instructions and harassment. Ask learners to identify the safety consequence, respectful communication and appropriate support/reporting route. The evaluator checks behavior-based reasoning and privacy, not forced personal disclosure. Approved providers must verify their current PSSR syllabus and any required update training; this lesson does not certify regulatory transition compliance.',[
 Q('Why can harassment affect operational safety?','It can harm people and suppress reporting or questions.','It is unrelated to teamwork.','It always improves discipline.','Only physical violence matters.','Psychological safety and respectful conduct influence communication.'),
 Q('What should a bystander avoid promising?','Absolute confidentiality beyond their control.','A respectful response.','Help reaching the reporting channel.','Immediate emergency help when needed.','Support should be honest about process and information handling.'),
 Q('What governs updated PSSR delivery?','Current applicable requirements and the approved provider syllabus.','An old course title alone.','The vessel paint scheme.','A generic attendance list.','Requirements can change and must be verified for the actual route.')]),
 L('Pollution prevention, safe work and human factors',
 'Marine safety includes protecting people and the environment during ordinary work. Prevent releases by confirming transfer destination, containment, valve arrangement and communication before moving fuel or waste. Discharge and waste handling follow the vessel procedures and applicable requirements; convenience is not permission to release material. Slips, falls, mooring lines, stored energy and enclosed spaces create serious hazards that need task-specific controls. A basic marine certificate does not qualify enclosed-space rescue or every deck operation. Human factors include fatigue, distraction, assumptions and hierarchy. Read-back, clear roles and a pause when information conflicts reduce errors. Reporting a near miss should produce a useful correction rather than punishment for raising a concern.',
 'A transfer team has a correct hose but an unconfirmed destination. The receiving tank level rises unexpectedly while another remains unchanged. The team stops through the agreed communication and verifies routing. The learning point is that equipment condition and correct line-up are separate checks. A junior worker who notices the mismatch must be able to speak up without waiting for rank-based permission.',
 'Create a fictional transfer brief showing sender, receiver, destination, capacity, stop communication and spill controls. Add one conflicting level reading and require a response. The evaluator checks separation of observed evidence from assumptions and respect for role boundaries. Actual transfer, mooring and enclosed-space work need their own procedures and demonstrated competence.',[
 Q('Does a sound hose prove a correct transfer?','No; routing and destination must also be verified.','Yes always.','Only for fuel.','Only if new.','Integrity and line-up are distinct controls.'),
 Q('Why encourage a junior worker to report conflicting readings?','Early information can prevent a release or injury.','Only senior ranks can observe hazards.','It replaces the master authority.','It eliminates all paperwork.','Useful reporting supports the command system.'),
 Q('Does Basic Training qualify enclosed-space rescue?','No; that requires its own capability and plan.','Yes for every mariner.','Only on small vessels.','Only if the rescuer is fit.','Basic marine safety and specialist rescue have different scope.')]),
 L('Approved training, practical proficiency and mariner records',
 'STCW Basic Training includes personal survival techniques, fire prevention and firefighting, elementary first aid, and personal safety and social responsibilities. The applicable national administration and approved provider route establish how competence is documented. In the United States, Coast Guard requirements distinguish initial training and routes for continued proficiency, refresher or revalidation; actual sea-service and course evidence matter. Do not assume a generic five-year date alone selects the correct route. Some skills cannot be maintained solely through routine shipboard service and need approved demonstration. An offshore survival credential is not automatically interchangeable with STCW Basic Training. Keep training certificates, practical results, sea-service evidence, medical status and mariner endorsement decisions distinct.',
 'A mariner has an offshore survival certificate and asks the employer to record STCW Basic Training complete. The topics overlap, but no automatic equivalence has been established. The planner verifies the Coast Guard-approved route and actual evidence. Another mariner has prior Basic Training plus sea service; the appropriate continued-proficiency route is determined from the current requirements and documented service rather than guessed from the certificate date.',
 'Build an evidence matrix for all four elements, separating knowledge, approved practical demonstration and administrative endorsement. A qualified provider evaluates actual skills and determines the applicable course route. The evaluator for this knowledge course checks that the learner can identify missing evidence without inventing equivalence. Verify current USCG guidance, including 2026 PSSR updates, before real enrollment or renewal decisions.',[
 Q('Are BOSIET and STCW Basic Training automatically interchangeable?','No.','Yes if both mention survival.','Only for oilfield vessels.','Only after one voyage.','Overlapping topics do not establish issuer equivalence.'),
 Q('What helps select a continued-proficiency route?','Current requirements and actual course/sea-service evidence.','A guessed universal date rule.','Only the worker age.','Only the employer preference.','The route depends on the applicable evidence and regulations.'),
 Q('Which four elements belong to Basic Training?','Survival, firefighting, elementary first aid, and personal safety/social responsibilities.','Navigation, welding, crane operation, and accounting.','Only survival and swimming.','Only firefighting and security screening.','The basic-training framework combines these four competency areas.')])
]);

export {programs};
export default programs;

add('OG34','mewp','This course teaches powered-access knowledge and supplies an evaluator rubric. IPAF PAL requires the approved theory/practical route; employer authorization, machine-category training, specific-model familiarization and an actual rescue plan remain necessary.',[
 L('Select the platform for the task and environment',
 'Mobile elevating work platforms differ in how they elevate, travel and reach. A vertical platform and a boom platform may reach the same height but create different access paths, stability conditions and entrapment exposures. Selection starts with the work position, reach, platform load, terrain, access dimensions, environment and rescue feasibility. Rated capacity includes people, tools and materials, not just the heaviest item. Indoor and outdoor use, wind limits and permitted slopes are machine-specific. A worker should not solve insufficient reach by standing on rails, boxes or ladders in the platform. Use an appropriate machine and plan the work so the operator remains in the designed position. Training for a category does not remove the need for model familiarization.',
 'A crew needs to reach over fixed pipework. A vertical lift reaches the elevation but cannot provide the needed horizontal access without leaning beyond the platform. Selecting it solely by height creates an unsafe work method. The planner evaluates a suitable alternative against reach, ground, load and overhead conditions. A larger machine is not automatically suitable if the access route cannot support or accommodate it.',
 'Compare two fictional machines with supplied manuals, capacities and reach envelopes. Learners choose a machine and justify every criterion, including why the rejected option fails. The evaluator checks that selection considers the complete task and environment. Actual category training and model familiarization use the real machine under a competent instructor.',[
 Q('Why can matching height still be an unsuitable selection?','Required horizontal reach and site conditions may not fit.','Height is the only criterion.','All platforms have identical reach.','Capacity never matters.','Access geometry and environment govern suitability.'),
 Q('What belongs in platform load?','People, tools and materials together.','Only the operator.','Only the largest tool.','Nothing carried in a bag.','The rated load applies to the total specified load.'),
 Q('How should insufficient reach be resolved?','Select and plan suitable access equipment.','Stand on the guardrail.','Add a ladder inside without approval.','Lean farther with a coworker holding you.','Improvised elevation defeats the designed protection.')]),
 L('Ground, travel path and changing stability',
 'Platform stability depends on the machine configuration and supporting surface. Holes, covers, trenches, slopes, soft ground and slab limitations can create hazards even when the platform is low. A surface that supports pedestrians may not support concentrated wheel or outrigger loads. Inspect the travel route and setup location, including overhead obstacles and vehicle interactions. Manufacturer restrictions govern elevated travel, slopes and stabilizer use. Do not infer permission from the fact that controls allow movement. Weather and water can change ground conditions during a shift. Barricades and route separation reduce collision exposure, while a competent assessment addresses support capability. The operator monitors changes and stops when the setup no longer matches the plan.',
 'A route crosses a cover that looks like the surrounding concrete. No load rating is available. The crew cannot treat visual continuity as proof of support; the route must be verified or changed. Later rainfall softens the setup area. A morning inspection does not permanently validate the afternoon ground state. The changed condition requires reassessment before movement or elevation.',
 'Mark a fictional route with a trench, cover, slope, doorway and truck crossing. Have learners explain the evidence needed at each point. The evaluator checks recognition of concentrated loading and change over time. Practical travel assessment occurs on a controlled route whose support and clearances have already been verified, not by experimenting with unknown surfaces.',[
 Q('Does pedestrian access prove a cover can support a MEWP?','No; concentrated machine loads need suitable evidence.','Yes if it feels solid.','Only if dry.','Only with one operator.','Support requirements differ between people and machinery.'),
 Q('Do enabled controls prove elevated travel is permitted?','No; manufacturer conditions govern.','Yes always.','Only on electric machines.','Only if the alarm is quiet.','Control capability is not an operating permission.'),
 Q('Why reassess after rainfall?','Ground support and traction may have changed.','The machine becomes lighter.','The manual no longer applies.','Rain only affects visibility.','Environmental changes can invalidate the original setup assumptions.')]),
 L('Inspection, controls and model familiarization',
 'Pre-use inspection checks the machine against the manufacturer procedure: structure, tires, leaks, guardrails, gates, controls, emergency functions, labels and other specified items. Functional checks test behavior in a safe area; they do not justify bypassing a failed interlock. Understand platform controls, ground controls, emergency stop and the actual emergency-lowering arrangement before elevation. Similar controls can have different enable logic or motion response. Familiarization includes where the manual is kept and how to communicate defects. A damaged gate, missing required guard or unexplained control behavior must be resolved through the appropriate removal-from-service process. Do not repair or adjust safety systems unless trained and authorized for that work.',
 'An operator trained on one model starts another and finds the ground emergency controls unfamiliar. The proper time to learn is before anyone is elevated. In a second case a platform gate will not close; tying it back removes protection rather than fixing the machine. The equipment is withheld for proper repair and verification.',
 'Using a secured machine and manufacturer checklist, have the learner identify controls and explain the response to planted nonhazardous training defects. The evaluator observes the actual inspection sequence and safe functional checks. Emergency-lowering practice uses the manufacturer procedure, trained personnel and a controlled plan; never simulate a failure by disabling a real safety system.',[
 Q('When should ground emergency controls be understood?','Before elevation.','Only after a breakdown.','Only at annual inspection.','After the operator leaves the site.','Emergency readiness must precede exposure.'),
 Q('What is the response to a gate that cannot close properly?','Withhold use and obtain proper correction.','Tie it open.','Use a coworker as a barrier.','Ignore it for a short task.','Required protective features must function as designed.'),
 Q('Does category training replace model familiarization?','No.','Yes on all electric lifts.','Only if colors match.','Only below a certain height.','Controls and emergency arrangements can differ by model.')]),
 L('Load, reach, wind and overhead entrapment',
 'Capacity and reach limits are coupled to the machine design and configuration. Side loads from pulling, pushing, attached sheets or snagged tools can introduce forces that a simple weight total misses. Wind acts on people, equipment and material surface area; large panels can behave like sails. Follow the manufacturer environmental limits and never invent a universal wind allowance. Overhead beams and structures can trap a person between the platform controls or rail and an obstruction. Plan the approach, keep visibility and use available protective systems as instructed. The operator must understand movement direction and stopping response before entering a restricted area. Electrical clearances require applicable rules and site planning; a platform is not assumed insulated.',
 'A fictional platform capacity is 500 pounds. Two workers weigh 180 and 170, and tools/materials weigh 120: total 470, leaving 30 pounds before the stated limit. That arithmetic does not approve carrying a large panel in wind or pushing against a structure. Those introduce other loads and constraints. A low overhead beam also creates entrapment risk independent of the capacity result.',
 'Calculate the total load and then identify three hazards the calculation does not address. In a safe ground-level simulation, ask the learner to plan an approach to a marked overhead restriction. The evaluator checks awareness of side load, wind, entrapment and electrical exposure. Actual movement assessment uses a controlled course and machine-specific criteria.',[
 Q('What is total platform load in the example?','470 pounds.','350 pounds.','120 pounds.','530 pounds.','180 plus 170 plus 120 equals 470.'),
 Q('Does being below capacity approve a large panel in wind?','No; wind and side-load limits also matter.','Yes automatically.','Only with two workers.','Only if the panel is light.','Surface area and force direction create additional effects.'),
 Q('Why plan the approach to overhead steel?','A worker can be trapped between platform and structure.','Only paint damage matters.','Guardrails eliminate every crush hazard.','The machine always stops automatically.','Entrapment is distinct from falling or overloading.')]),
 L('Fall protection, rescue and emergency lowering',
 'Fall protection follows the applicable rules, machine type and manufacturer instructions. Guardrails and gates provide designed protection but do not permit climbing out or standing on rails. Boom-type and vertical/scissor arrangements can have different requirements; do not copy one system onto every platform. When personal protection is required, use suitable equipment and the specified anchorage, with training in fit, compatibility and rescue implications. A rescue plan must address an incapacitated operator, failed platform controls, entrapment and access limitations. Ground personnel need the actual lowering knowledge and access to controls. Calling public emergency services is part of some plans but does not by itself demonstrate timely machine-specific rescue capability.',
 'A worker becomes unresponsive in an elevated platform. The designated ground responder knows the machine-specific emergency arrangement and follows the rescue plan while emergency medical help is activated. On another site, keys and ground controls are inaccessible and no one knows the procedure. The same machine capability cannot compensate for the missing human and access arrangements.',
 'Before a supervised drill, identify the machine, ground responder, communication, emergency controls, medical call and exclusion area. The evaluator observes a safe manufacturer-approved lowering exercise with no real casualty exposure. Score readiness and coordination, not improvisation. A rescue method requiring specialized access must be separately planned and practiced by capable personnel.',[
 Q('Are fall-protection requirements identical for every MEWP?','No; type, rules and manufacturer instructions matter.','Yes all use one universal arrangement.','Only height determines everything.','Only operator preference matters.','Platform designs and applicable requirements differ.'),
 Q('What can defeat an otherwise functional lowering system?','No trained responder or inaccessible controls.','A current operator card.','A clear manual.','A rehearsed communication plan.','Rescue capability includes people and access, not equipment alone.'),
 Q('Does calling emergency services alone prove rescue readiness?','No; the plan needs feasible machine-specific arrangements.','Yes in every location.','Only if the phone is charged.','Only for small platforms.','Response time and access must fit the actual emergency.')]),
 L('Observed operation and bounded authorization',
 'A practical operator assessment integrates selection, inspection, setup, control, observation, safe positioning and shutdown. Evaluate the category and model used, the relevant task and the site conditions. The learner should explain why a movement is safe, not only reproduce a joystick sequence. Errors such as bypassing an interlock, moving into an unverified surface or ignoring a stop instruction are critical and require intervention. Record assistance so a coached attempt is not presented as independent competence. After training, the employer authorizes the actual assignment and monitors changes in equipment, environment and performance. A PAL or other external card follows its issuer process; the VNDRLY knowledge result does not create one.',
 'A learner completes the course quiz but fails to notice a marked overhead restriction during supervised operation. The instructor stops the exercise, teaches the missed scanning behavior and reassesses in a safe setting. Issuing a practical pass from the quiz would conceal the actual gap. If the learner later changes to a different machine, familiarization and assignment review still apply.',
 'Use a task sheet with selection justification, inspection, safe travel, positioning, simulated work, emergency readiness and shutdown. The qualified evaluator defines manufacturer-based tolerances and stop criteria, records observations and conducts any retest. Keep knowledge completion, practical result, issuer card and employer authorization as separate evidence with matching scope.',[
 Q('What should happen after a critical scanning error in training?','Stop, remediate and reassess safely.','Pass because the quiz was correct.','Hide the intervention.','Continue into the obstacle.','Practical evidence must reflect actual performance.'),
 Q('What does the practical record need?','Machine/category, tasks, conditions, evaluator and observed result.','Only attendance.','Only a photo on the platform.','Only a generic signature.','Specific evidence supports bounded authorization.'),
 Q('Does VNDRLY knowledge completion issue an IPAF PAL card?','No.','Yes automatically.','Only after six lessons.','Only for indoor work.','IPAF certification follows its approved training and assessment route.')])
]);

add('OG43','rope','This is industrial rope-access knowledge preparation, not IRATA certification or a rigging/rope-maneuver manual. IRATA approved training and independent assessment, level-specific prerequisites, supervised practice and actual logged experience remain required.',[
 L('Choose rope access within a complete work system',
 'Rope access is a planned means of reaching and maintaining a work position, with protection, supervision and rescue integrated into the system. It should be selected after considering the task, alternatives, exposure and feasibility. A person skilled at recreational climbing is not automatically competent in industrial work, tools, chemicals or rescue. The access task and the trade task have separate competencies. Team composition must support the work and credible rescue, not simply meet the smallest headcount. IRATA arrangements include appropriate level supervision and a team rather than lone work. The work plan identifies location, hazards, exclusion areas, equipment, communications, weather limits and rescue arrangements before anyone is exposed.',
 'An inspector can perform the inspection technique on the ground but has no industrial rope-access qualification. Another worker is a rope technician but not qualified to interpret the inspection results. The project needs both competencies, either in the same appropriately qualified person or through a safe organized arrangement. A single generic certificate cannot establish both.',
 'For a fictional elevated inspection, compare scaffold, MEWP and rope access in terms of reach, duration, dropped objects, rescue and adjacent operations. The evaluator checks the reasoning and separates access competence from trade competence. This is a planning exercise; trainees do not rig or suspend themselves from an example drawing.',[
 Q('Does recreational climbing establish industrial rope-access competence?','No; the work system and competencies differ.','Yes automatically.','Only with strong grip.','Only for short jobs.','Industrial tasks include distinct equipment, supervision and rescue requirements.'),
 Q('Why separate access and trade qualifications?','Reaching the work does not prove ability to perform it correctly.','They are always identical.','It eliminates supervision.','Only paperwork differs.','Both the access method and work task require competence.'),
 Q('What should team size support?','The task and credible rescue arrangements.','Only the smallest possible wage cost.','A universal one-person method.','Only the shift length.','Minimum headcount does not establish adequate capability for every situation.')]),
 L('Equipment compatibility, inspection and traceability',
 'A rope-access system includes ropes, harnesses, connectors, devices, anchors and protective components that must be compatible and suitable for their intended use. A device designed for one rope type or diameter may not perform correctly on another. Inspection considers damage, wear, contamination, deformation, function and manufacturer retirement criteria. Textile damage can be chemical or thermal as well as visible abrasion. Traceability links an item to its identity, inspection history and status; a label cannot restore a damaged item. Quarantine suspect equipment so it cannot return accidentally to service. User checks and competent periodic inspections are complementary rather than interchangeable. Storage and transport should prevent contamination and damage before the equipment reaches the worksite.',
 'A rope has an unreadable identity and uncertain chemical exposure history. A clean appearance does not establish serviceability. The item is segregated for the competent equipment process rather than used because it feels strong. In another case a connector fits physically through a device but loads incorrectly; apparent fit is not proof of compatibility.',
 'Use decommissioned training samples and manufacturer information to classify acceptable, suspect and reject conditions. Require the learner to explain the consequence and traceability action. The evaluator observes that suspect items are isolated and that no destructive test is improvised. Actual equipment acceptance follows competent inspection and manufacturer criteria.',[
 Q('Does physical fit prove component compatibility?','No; intended loading and manufacturer requirements matter.','Yes always.','Only if the connector closes.','Only if colors match.','A connected system can still load a component incorrectly.'),
 Q('What follows uncertain chemical exposure of a rope?','Quarantine and competent disposition.','Use it if it looks clean.','Wash and assume full strength.','Hide the history.','Some damage cannot be ruled out by appearance alone.'),
 Q('Do user checks replace periodic competent inspection?','No; they serve complementary purposes.','Yes after one good check.','Only for new ropes.','Only indoors.','Inspection layers address different scopes and timing.')]),
 L('Independent protection, anchors and load paths',
 'Industrial rope-access protection depends on a planned system with suitable primary and backup functions. Redundancy is meaningful only if a single failure does not defeat both paths. Two ropes running over the same unprotected sharp edge share a common failure exposure. Anchor suitability involves strength, location, direction of loading, substrate and the complete connection, not just a convenient attachment point. Geometry affects forces; broad anchor angles can increase load on individual points. Calculations alone cannot validate an unknown structure. Qualified system design and approved rigging instruction govern actual arrangements. Learners should be able to trace the load path from worker through devices and ropes to the structure and identify where damage or misconfiguration could defeat protection.',
 'A fictional plan shows two independent-looking ropes attached separately but both crossing a hot pipe. The plan has two lines yet one common damaging condition. The correction must address routing and protection, not simply add another label saying backup. Another proposal uses a handrail as an anchor because it is nearby; proximity does not provide structural evidence.',
 'Trace two load paths on a tabletop schematic and mark common-mode hazards, edges, heat and unknown anchor evidence. The evaluator checks recognition of independence and structural uncertainty. Do not teach knots or construction of a life-support system from this diagram; practical rigging is performed only through qualified supervised training and verified site design.',[
 Q('Why are two ropes over one damaging edge not fully independent?','One hazard can damage both paths.','Two ropes never provide protection.','Only rope color matters.','The edge becomes stronger.','Redundancy must account for common-mode failure.'),
 Q('Does a nearby handrail prove a suitable anchor?','No; structural suitability requires evidence.','Yes if metal.','Only if painted.','Only for light workers.','Anchorage is an engineered load-path question.'),
 Q('What should a load-path review trace?','The complete connection from person to supporting structure.','Only the harness label.','Only the top rope color.','Only the equipment invoice.','Failure can occur anywhere in the supporting system.')]),
 L('Movement concepts, edges and tool control',
 'Ascending, descending, transfers and passing obstructions require level-specific instruction and observed practice. During changes of position, protection must be maintained through the taught sequence; a convenient shortcut can remove redundancy at the moment of greatest complexity. This knowledge lesson explains the purpose, not the manipulation sequence. Edges can damage ropes and alter device behavior, while lateral movement may create pendulum exposure. Tools and materials introduce dropped-object hazards and can affect balance or snag systems. Separate tool retention from life-support equipment according to the designed arrangement and manufacturer instructions. Exclusion areas must account for the possible trajectory of dropped items, not only the point directly below the technician.',
 'A technician proposes pulling sideways to reach beyond the planned work area. The lateral movement changes the potential swing path and rope contact points. The supervisor reassesses access and protection rather than treating reach as merely a personal preference. A tool tether attached to an unsuitable location can also interfere with devices; retention needs its own planned attachment and capacity.',
 'Use a drawing to identify edge contact, pendulum path, tool-drop exposure and adjacent workers. Ask the learner what changes when the work position moves laterally. The evaluator checks system awareness and rejects improvised maneuver instructions. Actual ascent, descent and transfers are taught on a controlled structure by qualified instructors under the relevant level syllabus.',[
 Q('What can lateral movement add?','Pendulum exposure and new rope contact points.','Guaranteed lower anchor load.','Automatic rescue access.','No change in hazards.','Changing geometry changes the system behavior.'),
 Q('Why plan tool attachment separately?','It can create interference, load and dropped-object hazards.','Any harness loop is always suitable.','Tools have no effect on rope work.','Only expensive tools need retention.','Tool control must not compromise life-support systems.'),
 Q('Can this written lesson qualify a transfer maneuver?','No; supervised practical instruction and assessment are required.','Yes after memorizing terms.','Only below ten feet.','Only with two ropes.','Life-support manipulation is a practical competency.')]),
 L('Rescue feasibility and suspended casualty planning',
 'Rescue planning begins before suspension and considers the actual work position, casualty condition, access, obstacles and available equipment. A plan that simply says call emergency services may not provide timely retrieval from the location. The team needs appropriate capability, communication and a method that does not expose rescuers to the same uncontrolled hazard. A casualty may be unable to cooperate, and a route suitable for one technician may not accommodate the rescue load or geometry. Suspension and illness require prompt medical response and careful handling according to trained procedures. Do not invent a universal rescue sequence or post-rescue medical position from folklore. IRATA rescue guidance and the site plan require competent selection, practice and review.',
 'A worker is positioned beneath an overhang that prevents a simple vertical recovery. The original plan assumes direct access from above and therefore does not match the site. Before work, the team develops and practices a feasible arrangement with the necessary personnel and equipment. If that cannot be demonstrated, the access plan is not ready even though every individual card is current.',
 'Conduct a tabletop rescue review with an incapacitated casualty, communication loss and an obstructed route. Require identification of equipment, people, load-path implications, medical interface and failure contingencies. A qualified instructor conducts any physical rescue drill on a controlled system. The evaluator records actual capability rather than a promise that somebody could improvise.',[
 Q('Why is the overhang important?','It can make the assumed recovery route infeasible.','It guarantees shelter from all hazards.','It reduces every rescue load.','It removes the need for communication.','Rescue geometry must match the actual position.'),
 Q('Do current individual cards prove the team rescue plan works?','No; the plan needs site-specific capability and practice.','Yes automatically.','Only if all cards match.','Only in daylight.','Team performance and site feasibility are separate evidence.'),
 Q('What should replace rescue folklore?','Current trained procedures and competent medical/rescue guidance.','A universal improvised sequence.','The fastest rumor.','An untested equipment combination.','Rescue and medical actions must be based on appropriate instruction.')]),
 L('Levels, logbooks, independent assessment and work records',
 'IRATA levels distinguish developing technician capability, more advanced skills and supervisory responsibility. Progression depends on the current scheme requirements, valid evidence and assessed competence; online knowledge cannot manufacture logged hours or experience. Logbooks should describe actual work accurately, with the required verification, rather than rounding up hours to meet a target. Training and independent assessment are distinct stages. An employer must still plan the job, provide suitable supervision and verify that the team can perform the assigned trade and rescue tasks. Changes in equipment, extended nonuse, performance concerns or task complexity may require refresher activity and reassessment according to the scheme and employer process.',
 'A candidate has many hours of ordinary ladder work and asks to count them as rope-access experience. The activities must be evaluated against the scheme definition and verified actual records; unrelated hours cannot be relabeled. In another case a technician passes a knowledge quiz but has not demonstrated a required practical skill. The result remains knowledge completion with practical assessment outstanding.',
 'Review fictional log entries for activity, dates, hours, role and verification. Identify unsupported claims and write an honest correction without changing actual history. A qualified instructor and independent assessor conduct the level-specific practical route. The evaluator for this course checks that the learner understands evidence integrity, supervision and the boundary between preparation and certification.',[
 Q('Can unrelated ladder hours be automatically relabeled as rope-access hours?','No; scheme definitions and actual verified work govern.','Yes if the total is large.','Only after a quiz.','Only with employer urgency.','Experience evidence must describe the activity actually performed.'),
 Q('Does training attendance equal independent assessment success?','No.','Yes after payment.','Only for renewals.','Only if the instructor signs attendance.','Participation and demonstrated competence are different events.'),
 Q('What does this course establish?','Rope-access knowledge preparation within its stated scope.','IRATA certification.','Verified practical hours.','Permission for lone rope work.','The external practical and experience route remains separate.')])
]);

const offshoreLessons={
 induction:L('Offshore installation hazards and emergency organization',
 'Offshore emergency readiness begins with understanding how the installation is organized. Production and drilling equipment can create fire, gas, pressure and dropped-object hazards, while marine conditions limit access and escape. Safety induction connects alarms to actions, muster to accountability, and temporary refuge to the emergency plan. A muster point is not automatically the final evacuation point. Emergency command determines evacuation arrangements using the actual hazard and available means. Work permits, simultaneous-operations coordination and isolation protect routine work before an emergency develops. Accommodation, helideck and process areas have different exposure profiles, so a route that is safe during normal work may be unavailable during a release. Workers need alternative routes and a way to communicate location if separated from their normal group.',
 'On a fictional platform, the normal corridor to muster is closed by a gas alarm. A worker follows the marked alternative route and reports to the designated controller. Another worker heads to the helideck assuming every emergency uses a helicopter. That assumption is unsafe: aviation availability and emergency command govern the actual evacuation. The first worker preserves both exposure control and accountability.',
 'Use an installation plan to identify alarm meaning, two routes, muster, temporary refuge and communication points. The evaluator introduces a blocked route and asks the learner to explain the safe alternative and reporting action. Deployment requires actual installation familiarization; this map exercise cannot prove knowledge of a platform the learner has never visited.',[
 Q('Is muster necessarily the final evacuation location?','No; the emergency plan defines subsequent actions.','Yes on every platform.','Only at night.','Only for contractors.','Accountability and evacuation are related but distinct stages.'),
 Q('Why not assume evacuation by helicopter?','Availability and emergency conditions determine the method.','Helicopters never serve platforms.','Only vessel crews may evacuate.','Aviation always ignores weather.','The actual emergency plan controls the evacuation arrangement.'),
 Q('What is required when using an alternate muster route?','Follow the safe plan and preserve accountability.','Leave without reporting.','Return for belongings.','Cross the alarmed area to save time.','Command needs to know who is safe and where.')]),
 briefing:L('Helicopter preparation and aircraft-specific briefing',
 'Passenger preparation includes accurate manifest information, baggage compliance, suitable clothing and the required survival equipment for the flight. The aircraft briefing identifies exits, restraints, lifejacket, emergency breathing equipment when fitted, brace guidance and crew commands. Similar-looking aircraft can have different exit mechanisms or seat arrangements. Identify the primary and alternative exit from the actual seat and pay attention to the physical reference points taught by the crew. Rotor areas, loading and approach directions are controlled by flight personnel; passengers do not improvise an approach based on a previous aircraft. Loose items can become hazards during rotor operations or an emergency. Fitness or equipment concerns should be raised before boarding so they can be addressed without pressure inside the aircraft.',
 'A worker trained on one helicopter boards another and assumes the exit handle works identically. During the briefing the worker notices a different arrangement and asks for clarification before departure. That question corrects a transfer error. A second passenger has changed body size since equipment fitting; the issue must be resolved through the operator process rather than forcing an unsuitable item closed.',
 'In a stationary trainer or classroom mock-up, ask learners to identify exits, restraints and equipment from several seat positions using the supplied briefing. Evaluate whether they notice differences instead of reciting a previous aircraft routine. Aircraft movement and rotor-area training require the aviation operator controls; never conduct unsupervised rotor demonstrations.',[
 Q('Why attend the briefing after previous helicopter experience?','Aircraft, seat and equipment arrangements can differ.','Only first-time passengers need it.','It is optional if swimming ability is good.','A certificate replaces crew instructions.','Prior experience can create incorrect assumptions.'),
 Q('Who controls passenger approach to an operating helicopter?','Authorized flight/ground personnel under the operator procedure.','Any passenger who arrived first.','The baggage owner.','A social-media diagram.','Rotor hazards require controlled aircraft-specific directions.'),
 Q('When should equipment fit concerns be raised?','Before boarding or departure through the operator process.','Only after an emergency.','Never if the card is current.','After tightening beyond comfort.','Fit problems must be resolved before exposure.')]),
 escape:L('Ditching, orientation and escape concepts',
 'Helicopter escape training prepares passengers for disorientation, restricted movement and changed aircraft orientation. The essential concept is an organized sequence learned for the aircraft and training variant, with reference points, restraints, exits and equipment used as taught. Releasing a restraint too early can remove a useful reference and make orientation harder; trying to carry bags obstructs escape. Water movement, darkness and inversion can make a memorized picture inadequate. These concepts explain why supervised practical exercises are necessary. They do not provide a safe self-training underwater sequence. The instructor controls progression, safety divers, communication and withdrawal arrangements in an approved facility. A learner who cannot complete an exercise safely needs individual support and reassessment, not pressure to conceal difficulty.',
 'In a dry trainer, a learner can point to an exit but becomes confused when the seat position changes. The instructor returns to reference-point recognition and practices with the new geometry before progressing. Passing a written exit-identification question did not prove the ability to maintain orientation. No water exercise is attempted until the training center requirements and safety arrangements are satisfied.',
 'Use dry, stationary mock-ups for the knowledge application. Have the learner explain why restraint timing, reference points and exit familiarity matter, without inventing a universal sequence. Approved-center assessors conduct and record actual escape exercises against the selected product. Critical errors, assistance and incomplete attempts remain visible in the record and require the provider remediation process.',[
 Q('Why can early restraint release make escape harder?','It can remove a reference and worsen disorientation.','It always improves orientation.','Restraints only affect comfort.','It guarantees access to every exit.','The taught sequence preserves orientation and control.'),
 Q('Does identifying an exit on paper prove underwater escape?','No.','Yes if the answer is quick.','Only with a current passport.','Only for experienced swimmers.','Practical performance must be observed in a controlled facility.'),
 Q('What is the appropriate response to difficulty in training?','Provider-supported remediation and reassessment.','Conceal it to obtain the card.','Practice alone underwater.','Skip all safety supervision.','Safe training recognizes individual performance needs.')]),
 ebs:L('Breathing-system variants and equipment familiarity',
 'Emergency breathing systems are not interchangeable simply because they are worn during offshore flight. Rebreather EBS and compressed-air EBS have different designs, limitations and training requirements. The selected OPITO product and aviation operator determine the equipment variant. Familiarization includes identification, fit, inspection indicators and the actual taught operation; a written explanation cannot establish breathing-system skill. Medical screening and training-center prerequisites address the demands of the exercise. A damaged seal, missing component or unfamiliar model is a readiness concern to resolve before flight or practical training. Do not infer serviceability from appearance alone or attempt improvised repairs. Underwater use, compressed-gas techniques and exercise sequences belong only in the approved supervised programme.',
 'A passenger holds a record for one breathing-system variant and is issued a different system. The matching words emergency breathing do not prove the training transfers. The operator and approved center verify the required familiarization or bridging route. The learner records the actual equipment variant rather than changing the old certificate description to match the new issue.',
 'With inert training equipment, the instructor asks the learner to identify the model, inspect the specified readiness indicators and explain when to refer an issue. The evaluator checks equipment recognition and honest limits. Actual activation and in-water assessment follow the approved center curriculum and safety controls. This exercise never instructs independent breath-hold or compressed-air experimentation.',[
 Q('Are rebreather EBS and compressed-air EBS automatically interchangeable?','No; their designs and training differ.','Yes if the colors match.','Only on short flights.','Only for strong swimmers.','The equipment variant must match training and operator requirements.'),
 Q('What should happen when an unfamiliar system is issued?','Verify the required familiarization or bridging route.','Relabel the old certificate.','Assume every control is identical.','Test it alone underwater.','Training evidence must match the actual system.'),
 Q('Where does in-water breathing-system assessment belong?','An approved supervised training environment.','A private pool without supervision.','A written quiz alone.','An improvised workplace tank.','Specialist safety controls are essential for these exercises.')]),
 sea:L('Sea survival, thermal protection and rescue communication',
 'Survival equipment supports flotation, thermal protection, visibility and organized rescue. A lifejacket and an immersion or survival suit have different functions and must be fitted and used according to the actual equipment instruction. Entering cold water can impair breathing and movement quickly; avoiding unnecessary immersion and using the planned evacuation method are important. Once separated from the installation or aircraft, group accountability and signaling help rescuers locate and recover survivors. Swimming effort, sea conditions, clothing and distance all affect endurance, so an apparently short distance is not a universal safe swimming target. Survival-craft boarding, water entry and recovery require supervised practice with the relevant equipment. Do not inflate equipment or jump into water based on an improvised classroom rule.',
 'A fictional evacuation reaches a survival craft with one person unaccounted for. The group reports the last known location and count through the emergency arrangement instead of sending an untrained person back into the hazard. Another learner proposes swimming toward a distant light; the instructor asks for distance, conditions and rescue-plan information, showing why visual impression alone cannot support the decision.',
 'Use a dry equipment station to identify flotation, thermal and signaling functions. On a tabletop map, track survivor count and last-known positions. The evaluator checks equipment-function distinctions and communication. Practical water entry, flotation, boarding and recovery are assessed at an approved facility under its medical, staffing and rescue requirements; no self-directed water exercise is assigned.',[
 Q('Do flotation and thermal protection describe the same function?','No; equipment may provide different protections.','Yes always.','Only in warm water.','Only with a whistle.','Keeping a person afloat and limiting heat loss are distinct needs.'),
 Q('What information helps when someone is missing?','Accurate count and last-known location.','A guess stated as certainty.','Only the person employer.','No report until everyone agrees.','Rescuers need timely reliable location and accountability information.'),
 Q('Does a visible distant light establish a safe swim?','No; distance, conditions and rescue planning matter.','Yes if it seems close.','Only after dark.','Only when wearing a jacket.','Appearance does not establish achievable safe travel in water.')]),
 fire:L('Offshore fire, smoke and self-rescue decisions',
 'Fire requires fuel, an oxidizer and sufficient heat; removing or separating one can interrupt combustion, but the response must match the material and conditions. Smoke can obscure routes and contain toxic products before flames are visible. Raise the alarm and follow the emergency plan. Extinguisher use is limited to the assigned trained role, suitable equipment and a safe escape route; a growing fire, heavy smoke or uncertain atmosphere can make withdrawal the correct action. Closing or isolating systems is performed only through the assigned procedure and role. Escape breathing equipment is for its specified purpose and is not automatically a firefighting respirator. Route familiarity and door discipline matter because uncontrolled movement can expose others or spread smoke.',
 'A small visible fire produces rapidly increasing smoke in a passage. A learner focuses only on extinguisher size and ignores the route becoming unusable. The correct analysis considers smoke, atmosphere and escape as well as flame size. The person raises the alarm and follows the safe escape arrangement rather than attempting an unassigned interior response.',
 'Use inert extinguishers and a smoke-free layout for the written-course application. Require the learner to choose between alarm/withdrawal and a permitted trained intervention based on supplied conditions. Approved practical firefighting and self-rescue exercises use the center safety controls and actual product requirements. The evaluator rejects any answer that assumes a small flame guarantees a safe atmosphere.',[
 Q('Why can a small visible fire still demand withdrawal?','Smoke and escape conditions may already be dangerous.','Flame size always proves safety.','Smoke is harmless outdoors.','An extinguisher guarantees success.','Atmosphere and escape can deteriorate before a large flame develops.'),
 Q('Is escape breathing equipment automatically firefighting equipment?','No; use is limited to its specified purpose.','Yes if it has a mask.','Only when new.','Only for a short entry.','Different respiratory equipment supports different duties.'),
 Q('What must remain available during permitted extinguisher use?','A safe escape route and conditions within training.','A camera recording.','A supervisor watching remotely only.','An unlimited fire growth allowance.','Intervention must not trap the worker.')]),
 aid:L('Offshore first aid and medical evacuation handover',
 'Offshore first aid links immediate care to the installation medical and evacuation system. Scene safety remains first: a collapse near a gas source or electrical hazard may require specialist rescue before access. Once safe, recognize life-threatening conditions, activate the medical response and use trained CPR/AED or bleeding-control skills as appropriate. Remote location makes concise information important: patient condition, event time, treatments, changes and access constraints support the medic and transport decision. A first aider does not independently determine aircraft suitability or invent a diagnosis. Equipment checks, responder coverage and communication rehearsals are part of preparedness. First-aid skills need current recognized practical assessment, even when the offshore survival course includes an emergency-care component.',
 'A worker is injured on a remote module. The caller reports precise deck location, consciousness, breathing, visible bleeding and safe access, while a trained responder gives care. The medic coordinates the next step. Saying only send a helicopter omits the clinical and operational information needed and assumes a transport decision outside the caller role.',
 'Run a manikin-based call and handover drill using a simulated medic. Assess scene safety, recognition, response activation, assigned care and factual handover. Physical CPR/AED and bleeding-control skills use the recognized instructor criteria. A written correct answer does not document those skills. Record the offshore communication interface separately from the clinical performance.',[
 Q('What makes the remote medical call useful?','Precise location, observed condition, care and access information.','Only a demand for a helicopter.','Only the worker job title.','An unverified diagnosis.','Medical and transport teams need factual situation information.'),
 Q('Does a gas-area collapse justify impulsive first-aider entry?','No; safe access and appropriate rescue are required.','Yes with a first-aid card.','Yes if the person is visible.','Only if the entry is brief.','First aid does not qualify hazardous-atmosphere rescue.'),
 Q('Who controls the medical evacuation arrangement?','The designated medical and emergency coordination system.','Any bystander choosing aircraft type.','The course website.','A passenger certificate alone.','Clinical and operational decisions require the assigned expertise.')]),
 initial:L('Initial training route and practical evidence',
 'Initial offshore survival preparation combines knowledge with physical emergency skills. BOSIET product variants distinguish equipment and regional requirements; a digital theory option still leads to approved-center assessment and required practical outcomes. Select the product that matches the employer and aviation arrangement before enrollment. The center checks its entry and medical requirements and controls water, fire, escape and first-aid exercises. A knowledge score is useful preparation but cannot prove physical performance under disorientation, equipment constraints or stress. Record the actual product, center, dates and verified result rather than issuing a generic offshore qualified label. Installation induction and employer authorization still connect the credential to deployment.',
 'A worker completes an online course and the planner marks all survival practicals complete. No center assessment or exercise record exists. The status must remain knowledge completed with practical requirements outstanding. The planner selects the appropriate approved product and obtains actual result evidence after delivery, preserving the difference between scheduled, attended and passed.',
 'Build an evidence map for induction, helicopter escape, sea survival, first aid and fire/self-rescue. For each, identify a knowledge check and a separately observed practical outcome. The evaluator looks for accurate status and matching product variant. For issuer certification, use the approved center process; VNDRLY supplies its own preparatory knowledge record only.',[
 Q('Does digital theory remove approved practical assessment?','No.','Yes for every product.','Only after a high score.','Only for experienced travelers.','Digital delivery changes theory access, not physical evidence requirements.'),
 Q('What should a credential record identify?','Actual product variant, center, dates and result.','Only offshore qualified.','Only the course price.','Only the employer logo.','Specific scope prevents unsupported equivalence claims.'),
 Q('Are scheduled and passed equivalent?','No.','Yes after payment.','Only for renewals.','Only when the employer is urgent.','An appointment is not a successful assessment.')]),
 huet:L('HUET assessment and passenger readiness',
 'HUET focuses on helicopter emergency preparation and escape capability within the selected product and equipment variant. It does not automatically cover the complete offshore induction, firefighting or marine basic-training curriculum. Practical assessment must match the actual approved course outcomes and be delivered in the controlled facility. Learners need to disclose relevant fitness concerns through the center process and understand the exercise stop and assistance arrangements. Confidence is not a performance measure; neither is swimming ability alone. The assessor observes the required actions, orientation and equipment use, records assistance and applies the product criteria. Before deployment, aviation-specific briefing and equipment fit remain necessary even with a current training record.',
 'A capable swimmer assumes no HUET practice is necessary. In a dry exercise the learner cannot locate the alternative exit from the assigned seat. The issue is aircraft orientation and trained sequence, not swimming speed. The instructor supplies focused instruction and later assesses the required practical outcomes safely. The record must not say completed merely because the learner attended the pool session.',
 'Create a readiness checklist with product variant, medical/entry review, equipment, briefing and observed assessment. The instructor uses a dry trainer for the knowledge portion. Approved assessors alone conduct the required in-water exercises. The evaluator checks that the learner can explain the difference between confidence, attendance and demonstrated capability without exaggerating the course scope.',[
 Q('Does strong swimming ability establish helicopter escape competence?','No; orientation and equipment skills are distinct.','Yes automatically.','Only in warm water.','Only after one flight.','The task requires specific practiced behavior.'),
 Q('Does HUET automatically include every BOSIET or STCW element?','No.','Yes universally.','Only with a current passport.','Only for platform workers.','Course scopes and issuer requirements differ.'),
 Q('What should an assessor record when assistance was needed?','The assistance and resulting performance accurately.','Independent success regardless.','Only attendance.','Nothing if the learner is confident.','Assessment evidence must reflect what was observed.')]),
 refresher:L('FOET eligibility, change review and skill decay',
 'Refresher training starts with eligibility for the selected product and an honest review of change. A previous certificate may be a prerequisite, but its product variant, validity and current provider rules must be checked. Equipment, aircraft arrangements, installation procedures and personal fitness can change between courses. Skills also decay when unused; familiarity with terminology can conceal difficulty performing the sequence. FOET is not simply a shorter initial course available to anyone. The approved center determines whether the person meets the prerequisite route and delivers the specified practical refresh and assessment. Record an expired or uncertain prerequisite as unresolved rather than altering dates or assuming a grace period.',
 'A worker presents an old survival certificate and requests FOET because the shorter schedule fits a rotation. The planner checks the actual product and date with the approved center. If the prerequisite is not accepted, the center identifies the appropriate route. Separately, a current holder receives new breathing equipment; the change still needs variant-specific review rather than relying on the expiry date alone.',
 'Give learners three fictional records: clearly matching, wrong variant and uncertain validity. They identify the verification question for each and list changed skills or equipment to discuss with the center. The evaluator checks honest status and individualized preparation. Practical refresh remains observed training; no record is renewed by this desk exercise.',[
 Q('Is FOET automatically available to anyone wanting a shorter course?','No; product prerequisites apply.','Yes after payment.','Only on weekdays.','Only for experienced swimmers.','Refresher eligibility is part of the approved product route.'),
 Q('What should happen with an uncertain prerequisite?','Verify it with the approved center before relying on it.','Invent a grace period.','Change the expiry date.','Assume all old cards qualify.','Eligibility must be supported by actual current rules.'),
 Q('Can a current date alone prove readiness for changed equipment?','No; equipment changes need review and training as required.','Yes always.','Only offshore.','Only for supervisors.','Validity and equipment familiarity are separate.')]),
 refreshCase:L('Integrated refresher scenarios and independent reassessment',
 'Refresher assessment should reveal whether the learner can still integrate the skill, not merely recall the answer from a previous course. Use the selected approved product exercises with meaningful variations such as a changed seat, alternative exit, equipment variation or altered emergency communication. Coaching belongs in training; the final observed result must distinguish independent performance from assistance. A critical unsafe action requires correction and reassessment under the center rules. Stress must be managed through safe progression and support, never by unsupervised exposure. After completion, retain the exact product result and update the employer readiness record without erasing previous evidence or implying unrelated qualifications.',
 'During a dry refresher, a learner repeatedly reaches toward the exit used on a previous aircraft despite a changed seating arrangement. The instructor identifies the habitual error, practices the correct reference for the current arrangement and reassesses. An attendance-only renewal would miss this predictable transfer problem. The final record describes the actual assessed product and result, not a claim that every offshore emergency skill is now universal.',
 'The evaluator prepares a change-focused observation sheet: recognition, orientation, equipment match, communication and safe response to difficulty. Approved-center practical outcomes remain the authority for the issuer record. The VNDRLY knowledge assessment asks the learner to explain the error mechanism and remediation. Record course completion, practical result and deployment acceptance as separate events.',[
 Q('What does a changed seat help reveal?','Whether the learner adapts reference points rather than repeating habit.','Only eyesight quality.','Whether the card is laminated.','Whether the flight is short.','Variation tests transfer of understanding.'),
 Q('How should coaching affect the evidence?','Record it and reassess independent performance as required.','Hide it in the final record.','Call it independent success.','Cancel all future training.','Assistance and demonstrated independence are different states.'),
 Q('Does a refresher renew unrelated occupational qualifications?','No.','Yes for all marine roles.','Only if the employer requests it.','Only for crane operators.','The result remains bounded to its actual product scope.')]),
};
add('OG17','offshore','OPITO BOSIET requires the selected approved product, medical/entry conditions and practical assessment. This original knowledge course is not OPITO digital-delivery accreditation and cannot issue BOSIET. Product-specific breathing and escape procedures remain approved-center instruction.',[offshoreLessons.induction,offshoreLessons.briefing,offshoreLessons.escape,offshoreLessons.sea,offshoreLessons.fire,offshoreLessons.aid,offshoreLessons.ebs,offshoreLessons.initial]);
add('OG18','offshore','OPITO HUET requires the selected product/variant and approved supervised practical assessment. This original course teaches passenger knowledge and escape concepts only; never practice underwater escape or breathing equipment independently.',[offshoreLessons.briefing,offshoreLessons.escape,offshoreLessons.ebs,offshoreLessons.sea,offshoreLessons.huet,offshoreLessons.refreshCase]);
add('OG19','offshore','OPITO FOET requires verified prerequisite eligibility, selected variant and approved practical refresh/assessment. This knowledge refresher does not renew an OPITO certificate. Current product-specific eligibility and equipment must be verified with the approved center.',[offshoreLessons.refresher,offshoreLessons.briefing,offshoreLessons.escape,offshoreLessons.ebs,offshoreLessons.fire,offshoreLessons.aid,offshoreLessons.refreshCase]);

const wellCore=[
 L('Hydrostatic pressure, depth and units',
 'Hydrostatic pressure comes from the weight of a fluid column. In common oilfield units, pressure in psi is approximately 0.052 × mud density in pounds per gallon × true vertical depth in feet. True vertical depth matters because hydrostatic head depends on vertical height, not the measured length of a deviated well. This relationship assumes a static, uniform-density column; real wells can have multiple fluids, gas, temperature effects and dynamic losses. Bottomhole pressure during circulation includes additional effects and cannot always be treated as static hydrostatic pressure. Keep units visible at each step and perform a reasonableness check before using a result. A calculation with the right digits but the wrong depth is still wrong. These are learning calculations, not operational setpoints.',
 'A fictional well has 10 ppg fluid and 8,000 ft true vertical depth, with 10,000 ft measured depth. Static hydrostatic pressure is 0.052 × 10 × 8,000 = 4,160 psi. Using measured depth would give 5,200 psi, overstating head by 1,040 psi. That error could conceal an underbalanced condition on paper. The example assumes a full uniform column and does not establish the pressure in a real well.',
 'Require learners to calculate both results, label the assumptions and explain physically why a longer deviated path does not create the same extra vertical head. The evaluator checks units, depth selection and recognition of the static assumption. Actual well calculations require validated well data, approved worksheets and independent checking under the selected accredited training and operating system.',[
 Q('Which depth belongs in the uniform static hydrostatic formula?','True vertical depth.','Measured depth regardless of trajectory.','Horizontal displacement.','Total pipe length on the rack.','Fluid head depends on vertical height.'),
 Q('What is the fictional hydrostatic pressure?','4,160 psi.','5,200 psi.','416 psi.','8,000 psi.','0.052 × 10 × 8,000 equals 4,160.'),
 Q('Does the static result include every circulating pressure effect?','No; dynamic effects need separate treatment.','Yes universally.','Only when the well is deviated.','Only with a digital calculator.','The formula has explicit physical assumptions.')]),
 L('Pressure balance, influx and loss mechanisms',
 'A well-control problem involves the relationship among formation pressure, wellbore pressure and the ability of the formation and equipment to contain pressure. If wellbore pressure at a permeable formation falls below formation pressure, an influx can enter. Excessive pressure can fracture formation or produce losses; losing fluid can then reduce hydrostatic support. The operating window is therefore bounded on both sides. Swab and surge describe pressure changes associated with pipe movement, while fluid-level changes and density changes affect static support. Gas can expand as pressure decreases during upward movement, changing volume and behavior. Recognizing the mechanism is essential before choosing an approved response. A trend may have several possible causes, so communicate observations promptly instead of waiting for a perfect diagnosis.',
 'In a fictional static model, formation pressure is 4,300 psi and hydrostatic pressure is 4,160 psi. The difference is 140 psi underbalance before any other effects. Increasing density might address one mechanism, but the acceptable density also depends on fracture limits and the approved plan. In a separate loss scenario, the crew cannot assume that less return flow means a benign measurement fault; loss of fluid can undermine the primary barrier.',
 'Ask learners to classify five changes: lower fluid level, increased density, rapid pipe movement, gas expansion and lost returns. They must explain the mechanism and identify missing data, not prescribe a field action. The evaluator checks recognition of both influx and loss risk and rejects a one-direction rule that more pressure is always safer.',[
 Q('What is the pressure difference in the worked static example?','140 psi underbalance.','140 psi overbalance.','8,460 psi underbalance.','No difference.','4,300 minus 4,160 equals 140.'),
 Q('Why is more pressure not always safer?','It can exceed formation or equipment limits and cause losses.','Pressure has no effect.','Only temperature matters.','A barrier cannot fail at high pressure.','The operating window has upper as well as lower bounds.'),
 Q('Why can lost returns threaten well control?','Loss of fluid may reduce hydrostatic support.','Losses always increase fluid height.','They prove no formation is permeable.','They eliminate influx potential.','A loss event can compromise the pressure-supporting column.')]),
 L('Barrier functions and equipment evidence',
 'A barrier is a defined function supported by identified elements and evidence, not simply a piece of equipment painted a certain color. A fluid column can provide a pressure barrier when its height, density and integrity are suitable. Mechanical pressure-control equipment has operating envelopes, compatibility limits and failure modes. Identify the path the barrier must block and how its effectiveness is verified. A test record should connect the actual equipment, test conditions, acceptance criteria, time and result. A certificate from a different configuration does not establish current integrity. Maintenance, line-up changes, wear and temporary bypasses can change barrier status. Distinguish equipment available, tested and actively serving a barrier function; those are not synonymous states.',
 'A pressure-control assembly has a recent test document, but an important component was changed afterward. The document supports the old tested state, not automatically the new configuration. The team needs the required verification for the changed assembly. In another case, a full fluid column is assumed while a loss event is unresolved; the assumed barrier must be reassessed against the actual fluid state.',
 'Draw a simple fictional barrier schematic and trace possible flow paths. For each proposed barrier, identify the function, supporting element, evidence and a change that would invalidate that evidence. The evaluator checks that the learner notices configuration changes and does not equate a component list with a demonstrated barrier. Practical equipment operation belongs in approved training and the actual operating procedures.',[
 Q('What invalidates automatic reliance on the old test in the case?','A component change altered the tested configuration.','The document has a date.','The equipment is expensive.','A second worker read it.','Test evidence applies to its actual scope and state.'),
 Q('What should a barrier description identify?','The function, elements and evidence of effectiveness.','Only the equipment color.','Only a manufacturer name.','Only the purchase order.','A barrier must interrupt an identified hazard path.'),
 Q('Are available and verified-active barrier states identical?','No.','Yes whenever equipment is nearby.','Only on land rigs.','Only after shift change.','Presence does not prove correct function or line-up.')]),
 L('Detection, volume accounting and disciplined communication',
 'Well monitoring combines flow, volume, pressure and operational context. Unexpected flow with pumps stopped, unexplained pit gain and deviations in expected fill or displacement can indicate an influx, but interpretation must consider transfers, equipment changes and measurement quality. The correct response follows the approved procedure for the role and operation; it should not wait for every indicator to agree. Volume accounting compares expected and observed movement. A difference needs investigation and clear communication, not retrospective adjustment of records to make them match. During trips, expected displacement depends on the actual tubular geometry and conditions. Record time, activity, relevant readings and any confounding transfer so the driller or supervisor can assess the pattern.',
 'A fictional activity predicts a 6-barrel volume change, but the measured change is 10 barrels and a 2-barrel transfer is independently documented. The unexplained difference is 2 barrels after accounting for that transfer. This does not identify the cause by itself. It is a discrepancy to report and handle under the well-control procedure, with the original readings preserved.',
 'Give the learner a short event log containing pumping, a transfer and volume readings. Require an accounting table separating observed, expected and explained changes. The evaluator checks arithmetic and whether the learner reports the residual promptly without inventing a cause. Simulator assessment should introduce ambiguous indicators and evaluate recognition and procedural response, not reward silent guesswork.',[
 Q('What unexplained difference remains in the case?','2 barrels.','4 barrels.','6 barrels.','10 barrels.','10 observed minus 6 expected minus 2 documented transfer equals 2.'),
 Q('What should happen to original inconsistent readings?','Preserve them and report the discrepancy.','Edit them to match expectation.','Delete them after discussion.','Average them without explanation.','Accurate observations support diagnosis and learning.'),
 Q('Must every indicator agree before reporting a concern?','No; follow the approved recognition and response procedure.','Yes always.','Only if the supervisor is nearby.','Only during drilling.','Waiting for certainty can delay necessary response.')]),
 L('Calculation discipline and controlled method selection',
 'Well-control calculations connect measured pressures, fluid density, depth and equipment limits. A commonly taught idealized density increment is additional pressure divided by 0.052 times true vertical depth, in ppg when pressure is psi and depth feet. This mathematical relationship does not choose a kill method, validate pressure data or authorize changing the well. Driller, Wait and Weight and other methods have different sequences, prerequisites and pressure-management requirements; they must be taught and assessed through the chosen discipline and level using approved worksheets and simulation. Distinguish initial data, calculated targets and actual monitored response. Independent checking should examine assumptions and units as well as arithmetic. A plausible-looking answer is not evidence that the inputs were measured under appropriate conditions.',
 'For a fictional exercise only, a validated static pressure increment of 520 psi at 10,000 ft TVD corresponds to 520/(0.052 × 10,000) = 1.0 ppg. Added to a 10.0 ppg starting fluid, the mathematical result is 11.0 ppg. This is not a field recommendation: fracture limits, equipment limits, actual well state and approved method are intentionally unspecified.',
 'The learner must calculate the result, state every assumption and name the missing operational constraints. The evaluator rejects a correct number presented as authorization. In an accredited simulator session, use the discipline-specific calculation sheet and observe method execution, pressure interpretation and communication. This course supplies conceptual preparation and error recognition, not a live-well sequence.',[
 Q('What is the calculated density increment in the example?','1.0 ppg.','0.1 ppg.','10 ppg.','520 ppg.','520 divided by 520 equals 1.0.'),
 Q('What prevents using the result as a field instruction?','The actual well state, limits and approved method are unspecified.','The arithmetic is impossible.','Density never affects pressure.','Only handwritten numbers are valid.','Correct arithmetic cannot supply missing operational evidence.'),
 Q('What should independent checking examine?','Inputs, assumptions, units and arithmetic.','Only the final digits.','Only the calculator brand.','Only the signature.','Most consequential errors can occur before arithmetic.')])
];
const wellLast=(issuer)=>L(`${issuer} scenario assessment, level selection and handover`,
 `Choose the ${issuer} discipline, level and equipment scope that match the intended responsibility. Awareness, operational and supervisory duties are not interchangeable. Surface and subsea arrangements introduce different equipment and response considerations; drilling and well-servicing tasks likewise need their own curriculum. An integrated scenario tests whether a learner recognizes a deviation, communicates facts, applies the approved procedure and maintains barrier awareness while conditions evolve. Written calculation success alone cannot demonstrate simulator performance. A handover must preserve the current well state, barrier status, trends, unresolved questions and the authority for next actions. Rushed shifts and ambiguous phrases such as stable can conceal critical assumptions. Use a structured record with time and units rather than relying on memory.`,
 'In a fictional simulator handover, the outgoing operator says pressures are fine but omits a recent unexplained volume change and a disabled instrument. The incoming team cannot interpret the remaining readings correctly. The corrected handover identifies the deviation, available instruments, current barrier state and pending decision. The assessment then changes one reading to see whether the learner integrates the new evidence instead of repeating the original plan.',
 `The evaluator uses a safe simulator and the current ${issuer} approved assessment process for any issuer credential. For this knowledge course, score the written handover, recognition of missing data and explanation of role limits. Record calculation errors separately from communication and procedural errors. Require remediation and an independent repeat; never label a tabletop exercise as completed simulator assessment.`,[
 Q('Why specify level and equipment scope?','Different roles and configurations need different competencies.','All certificates cover every well task.','It only changes the card color.','It eliminates practical assessment.','Qualification must match responsibility and equipment.'),
 Q('What is missing from pressures are fine?','Readings, context, barrier state and unresolved conditions.','Nothing.','Only the weather forecast.','Only the shift meal order.','A handover must communicate the actual state and uncertainty.'),
 Q('Does a written calculation pass establish simulator competence?','No; observed scenario performance is separate.','Yes if all digits are right.','Only for subsea wells.','Only after a long course.','Knowledge and integrated practical performance require distinct evidence.')]);
add('OG16','well','IADC WellSharp credentials require the selected accredited discipline/level, examinations and applicable practical/simulator assessment. This original VNDRLY course is well-control knowledge preparation; it supplies no live-well operating sequence or proprietary syllabus-equivalence claim.',[...wellCore,wellLast('IADC WellSharp')]);
add('OG42','well','IWCF credentials require the selected approved programme, level, surface/subsea scope and applicable written/practical assessments. This original VNDRLY course assesses well-control foundations and calculation reasoning; it does not claim completion of the full IWCF syllabus or simulator competence.',[...wellCore,wellLast('IWCF')]);

add('OG13','cdl','This is commercial-driving knowledge preparation, not a CDL, endorsement or registered ELDT completion. The state licensing agency, FMCSA-registered training provider where applicable, behind-the-wheel instruction and required examinations control the credential route.',[
 L('Vehicle classes, endorsements and the training route',
 'Commercial-driving eligibility is a combination of vehicle class, operation, endorsements, restrictions and driver status. Start with the actual vehicle and combination ratings, cargo and passenger use; do not infer eligibility from a pickup-like cab or a job title. A license restriction can prohibit an otherwise familiar vehicle configuration. Tank, hazardous-material, passenger and school-bus duties have distinct endorsement considerations. Entry-Level Driver Training applies to specified first-time Class A or B licenses, upgrades and first-time S, P or H endorsements, subject to the applicable rules and exceptions. Required training must be recorded by a provider on the Training Provider Registry. Theory completion is not behind-the-wheel completion, and neither is the state license. Medical qualification and employer authorization are additional checks, not hidden substitutes for licensing.',
 'A driver licensed for one configuration is assigned a combination with different braking or transmission characteristics and a cargo requiring an additional endorsement. The dispatcher cannot conclude that a CDL of any kind is sufficient. The assignment review compares the actual vehicle and cargo with the class, endorsements and restrictions, then identifies any required training and testing before dispatch.',
 'Give learners a fictional vehicle specification, cargo description and redacted license. Require a line-by-line eligibility comparison and a sequence of outstanding steps. The evaluator passes only a reasoned match, not a declaration that the driver is experienced. For an actual candidate, use the current state manual and registered provider curriculum rather than this abbreviated fictional specification.',[
 Q('What determines whether a license fits the assignment?','Class, endorsements, restrictions and the actual vehicle/use.','Only possession of any CDL.','The truck paint color.','The dispatcher preference.','Eligibility is specific to the vehicle and operation.'),
 Q('Does theory completion prove behind-the-wheel completion?','No.','Yes if the score is high.','Yes after watching a video.','Only if printed.','Driving performance requires its separate training and evaluation.'),
 Q('Where must applicable ELDT training be provided?','Through a provider meeting the Training Provider Registry requirements.','Any unregistered website.','Only a coworker conversation.','A course title alone is enough.','Applicable ELDT has a regulated provider and reporting route.')]),
 L('Inspection, braking concepts and defect decisions',
 'Vehicle inspection connects a visible condition to its consequence. Tires affect contact and load support; steering controls direction; brakes convert motion to heat; suspension and frame transmit loads; lights and mirrors support detection and communication. Air-brake systems have stored-pressure and warning functions that require system-specific instruction and tested driver competence. A warning cannot be dismissed because the vehicle moved normally yesterday. Inspection should follow a consistent sequence and include the combination, coupling and cargo securement where relevant. Written defect reporting preserves what was found and how it was resolved; a signature without an actual check is not evidence. Maintenance personnel perform repairs within their competence, and dispatch pressure cannot change a safety-critical defect into an acceptable condition.',
 'During a pretrip inspection a learner finds a damaged tire and a brake warning. The scheduled journey is short, but distance does not remove the failure mechanism. The vehicle is held for the appropriate evaluation and repair process. After correction, the driver verifies the required release evidence and repeats relevant checks. Simply swapping drivers would not resolve either defect.',
 'In a stationary secured training vehicle, an instructor demonstrates the inspection sequence and safe access. The learner explains each checked item and consequence, identifies planted training defects and records a disposition. Use the state/provider procedure for brake-system tests; this text intentionally does not invent pressure thresholds or a universal air-brake test sequence.',[
 Q('Does a short route make a brake warning acceptable?','No; the warning requires proper evaluation.','Yes under five miles.','Yes if unloaded.','Only in daylight.','Trip length does not establish braking capability.'),
 Q('What makes an inspection more than a checklist signature?','Actual observations linked to condition and disposition.','A neat pen.','The earliest timestamp.','Copying yesterday findings.','Inspection evidence must describe the current vehicle.'),
 Q('What should teach the specific air-brake test?','The applicable state/provider procedure and vehicle instruction.','A guessed universal sequence.','A social-media comment alone.','The driver memory of another system.','System-specific competence and current criteria are necessary.')]),
 L('Space management, stopping distance and backing',
 'A moving vehicle needs space for perception, reaction and braking. Distance traveled during reaction equals speed multiplied by time, using consistent units. Braking distance grows rapidly with speed and changes with traction, grade, load and brake condition; a simple dry-road demonstration is not a guarantee. Increase separation when visibility or traction deteriorates and avoid driving faster than the distance in which hazards can be detected and safely managed. Large vehicles have blind areas and off-tracking in turns. Backing exposes areas the driver may not see; plan to minimize it, inspect the path safely and use agreed spotting communication when required. If a spotter disappears from view or communication fails, stop. A reversing alarm warns others but does not prove the path is clear.',
 'At 55 mph a vehicle travels approximately 80.7 feet each second. A 1.5-second reaction interval adds about 121 feet before braking distance is considered. At 35 mph the same interval adds about 77 feet. This original arithmetic shows why attention and speed matter, but cannot predict the actual total stopping distance. At a crowded yard the safer route may eliminate a reverse move entirely rather than relying on a louder alarm.',
 'Calculate reaction travel using mph multiplied by 1.467 to obtain feet per second. Explain what additional factors determine stopping. In a controlled driving course, the instructor observes scanning, separation, turns and backing using the provider criteria. Never create a surprise obstacle in live traffic to test reaction.',[
 Q('Approximately how far is traveled in 1.5 seconds at 55 mph?','121 feet.','12 feet.','55 feet.','550 feet.','55 × 1.467 × 1.5 is about 121.'),
 Q('Does that number include braking distance?','No; it is reaction travel only.','Yes all stopping components.','Only on wet roads.','Only with air brakes.','Braking adds distance after reaction travel.'),
 Q('What follows loss of the backing spotter?','Stop until the path and communication are safely reestablished.','Keep reversing slowly by assumption.','Sound the horn and continue.','Accelerate to finish.','The agreed visibility and communication control has failed.')]),
 L('Cargo, combinations and tank dynamics',
 'Cargo changes vehicle weight distribution, center of gravity, axle loads and handling. Securement must resist expected movement using the applicable rules, rated components and cargo-specific methods. A tiedown label alone does not prove the entire arrangement: anchor points, angles, damage and cargo strength matter. Coupling integrity requires an actual inspection and the vehicle-specific procedure. Liquid cargo can shift even when the total mass is unchanged; surge and a high center of gravity affect braking and cornering. Baffles do not eliminate every surge direction. Tank and hazardous-material endorsements address distinct matters and may both be relevant. Drivers must know the load information needed for safe operation, including shipping papers and emergency information where applicable, without pretending a general driving course qualifies hazardous-material response.',
 'A tank vehicle is partly filled. The driver assumes it is safer in every respect than a full tank because it weighs less. Lower mass does not remove liquid movement; changes in speed and direction can produce surge. The route and driving behavior must account for that dynamic. In another case, securement hardware is rated but attached to an unsuitable point: the weakest part of the system remains inadequate.',
 'Use a tabletop model or instructor-controlled demonstration to show how a shifting load changes balance. Have learners identify securement-system components and distinguish tank qualification from hazardous-material qualification. The evaluator requires explanation of dynamic effects and actual inspection criteria. Do not practice emergency maneuvers with live hazardous cargo.',[
 Q('Why can a partially filled tank still be challenging?','Liquid movement can affect vehicle stability and braking.','Its cargo becomes weightless.','Baffles remove every dynamic effect.','Only full tanks move.','Surge is a movement problem as well as a mass problem.'),
 Q('Does rated hardware prove the whole securement system?','No; anchors, arrangement and cargo interface also matter.','Yes automatically.','Only if shiny.','Only with two tiedowns.','The complete load path needs adequate capacity and configuration.'),
 Q('Are tank and hazardous-material endorsements interchangeable?','No; they address different qualifications.','Yes in every state.','Only for water.','Only for night driving.','The assignment may require distinct endorsements.')]),
 L('Fatigue, hours, route planning and emergency decisions',
 'Legal hours and actual fitness are related but not identical. A driver can be within an hours limit and still be impaired by fatigue, illness or medication effects. Property-carrying and passenger-carrying rules differ, and exceptions require the actual qualifying conditions; an oilfield destination alone is not proof that an exception applies. Trip planning includes travel time, breaks, inspection, loading, weather, parking and delay contingency. Unrealistic schedules encourage unsafe choices. In emergencies, control the vehicle within training, protect the scene without entering traffic unnecessarily and communicate precise location and hazards. A roadside hazardous-material release requires the emergency information and response plan; a driver should not improvise spill intervention outside training.',
 'A dispatch plan assumes four hours driving and no time for inspection, loading queues or required breaks. A two-hour queue consumes the contingency that never existed. The driver reports the changed arrival estimate and replans within applicable rules and actual fitness. Recording waiting time inaccurately to preserve the original schedule would corrupt the compliance record rather than solve the delay.',
 'Build a fictional trip timeline with inspection, driving, waiting, rest and delivery events. Require learners to identify which current rules they must consult and to separate fatigue observations from legal-hour arithmetic. The evaluator checks truthful records, realistic contingency and willingness to stop when unfit. Verify actual exceptions from official sources before applying them to a real assignment.',[
 Q('Does legal available time guarantee fitness to drive?','No; fatigue or illness can still impair the driver.','Yes always.','Only for experienced drivers.','Only on highways.','Compliance limits are not a complete fitness assessment.'),
 Q('Does an oilfield destination automatically create an exception?','No; the specific qualifying conditions must be met.','Yes for every carrier.','Yes if cargo is urgent.','Only after midnight.','Exceptions depend on the rule and operation, not a label.'),
 Q('What should change after an unplanned delay?','The schedule and plan, using truthful time records.','The recorded clock to hide the delay.','The vehicle speed limit.','The driver medical status.','Planning must adapt without falsifying evidence.')]),
 L('Behind-the-wheel evaluation and licensing evidence',
 'Driving competence requires integrated performance: inspection, control, observation, communication, judgment and safe interaction with traffic. A learner may recite a backing rule yet fail to stop when the spotter disappears. Assessments therefore observe behavior under suitable controlled and road conditions through the registered provider and state process as applicable. The evaluator records task, vehicle, conditions, assistance and errors; a coached successful attempt is different from independent performance. Theory gaps should be remediated before exposure to a demanding road task. After licensing, the employer still verifies the assignment, vehicle familiarity, endorsements, restrictions and fitness. Keep the actual license and medical status distinct from training certificates and from a VNDRLY knowledge achievement.',
 'A learner passes written questions but repeatedly misses trailer off-tracking during turns in the controlled course. The correct response is targeted instruction and further observed practice, not issuing a driving pass because the written score is high. When the learner later demonstrates safe independent turns, the provider records that performance through its process. The state licensing decision remains separate.',
 'Prepare an evaluation matrix for pretrip, basic control, backing, turns, road scanning and hazard response. For each, specify observable behavior and an unsafe condition that stops the exercise. Actual ELDT and licensing assessments use current authorized criteria and qualified instructors. This paper matrix helps learners understand evidence quality but does not claim provider registration or submit a training record.',[
 Q('What does a strong theory score establish?','Knowledge performance, not safe driving performance by itself.','Every driving skill.','A state license.','A medical certificate.','Written and behind-the-wheel evidence measure different outcomes.'),
 Q('How should coached performance be recorded?','As assisted practice, with independent reassessment when required.','As unassisted success.','Without mentioning coaching.','As a license renewal.','Accurate evidence distinguishes learning from demonstrated competence.'),
 Q('Who issues the CDL?','The authorized state licensing agency.','VNDRLY automatically.','Any employer after a quiz.','A truck manufacturer.','Training supports the licensing route but does not replace it.')])
]);

add('OG14','twic','TWIC is a TSA-issued identity/security credential, not an occupational qualification. VNDRLY certifies only maritime-access knowledge. TSA enrollment, threat assessment, card status and facility-specific access decisions remain external. Direct TSA pages returned 403 during review; do not teach unverified fees, processing promises or renewal eligibility.',[
 L('What TWIC proves and what it does not',
 'TWIC supports identity and security screening for applicable unescorted access to secure areas of maritime facilities and vessels. It is not evidence that a person can operate a crane, handle cargo, enter a confined space or perform marine emergency duties. Access has several layers: identity, valid credential status, business purpose, facility permission and task authorization. Passing one layer does not automatically satisfy the others. The facility security plan and security personnel determine the permitted access arrangement. A worker should know the approved entry point, required identification, sponsor or contact and intended work area before travel. Treat an access denial as a condition to resolve through the designated process rather than a challenge to bypass.',
 'A contractor presents a valid TWIC at a terminal but has no work order or site sponsor. The card may satisfy one identity/security element; it does not establish a business reason or local permission. The gate contacts the sponsor and follows the facility process. If access is later granted, the worker still needs the relevant task qualifications and site induction before work.',
 'Sort fictional evidence cards into identity, credential status, business purpose, local access and occupational competence. Explain why none should be silently substituted for another. The evaluator checks that the learner can describe a legitimate access-resolution route without tailgating or sharing credentials. This is a practical desk exercise in access reasoning, not security-officer qualification.',[
 Q('Does a valid TWIC prove crane-operating competence?','No.','Yes at every port.','Only if the card is new.','Only for contractors.','Identity/security screening is not occupational skill evidence.'),
 Q('Why might a cardholder still be denied entry?','Local permission or business purpose may be unverified.','TWIC always guarantees all access.','Only permanent employees can hold cards.','The card replaces the security plan.','Facilities apply their own lawful access controls.'),
 Q('What is the appropriate response to an unresolved gate issue?','Use the designated sponsor/security process.','Follow another vehicle through.','Borrow a coworker card.','Enter through an unstaffed opening.','Resolve the condition without defeating access controls.')]),
 L('Enrollment, identity evidence and accurate applications',
 'TSA controls enrollment and security-threat assessment. Applicants use the official enrollment route, verify accepted identity documentation and provide accurate information. Requirements and appointment arrangements can change, so use the current official instructions rather than a copied fee table or an old screenshot. A training provider cannot guarantee approval or bypass the assessment. An employer may help a worker plan scheduling, but should not collect unnecessary background-check details in a routine training record. Distinguish application submitted, appointment completed, assessment pending, approved and card received. These statuses describe different events and none should be fabricated to meet a mobilization date. If the agency requests additional information, use its secure process and authorized assistance rather than uploading sensitive documents to a general team chat.',
 'A worker has an appointment confirmation and is scheduled to mobilize the next day. The confirmation proves an appointment, not a valid card or access approval. The project planner records the true status and arranges only the access options the facility permits. A third-party advertisement promising guaranteed immediate approval is not a substitute for the TSA decision.',
 'Create a fictional application timeline using only status labels and dates; do not use real identity numbers. Ask the learner to identify which status supports which statement and which information belongs in the secure enrollment process. The evaluator rejects claims of guaranteed approval, invented processing times and collection of unnecessary personal records.',[
 Q('What does an appointment confirmation establish?','A scheduled enrollment event, not card issuance.','A valid TWIC.','Automatic facility admission.','Completion of every background check.','Application milestones must be represented accurately.'),
 Q('Where should sensitive enrollment evidence go?','Through the official secure enrollment process.','A public training discussion.','An unrestricted shared spreadsheet.','A social-media message.','Identity and security data need appropriate handling.'),
 Q('Can a training vendor guarantee TSA approval?','No.','Yes after a quiz.','Yes if the course is expensive.','Only for oilfield workers.','The issuing agency controls the assessment and decision.')]),
 L('Arrival, verification and escort boundaries',
 'Prepare for arrival by confirming the entry location, expected sponsor, permitted time, vehicle requirements and local escort arrangements. Present your own credential as requested and allow the authorized verification process. A card visible through a windshield may not complete the facility checks. Escort rules are facility-specific controls, not a universal privilege held by every cardholder. An escort must follow the assigned conditions, including areas, accountability and continuity of control. If the escort arrangement fails or changes, stop movement and contact security rather than wandering to find the worksite. Site maps and access permissions should be used for the authorized purpose and not circulated unnecessarily.',
 'A delivery worker is admitted under escort to a specified unloading location. The escort is called elsewhere and suggests the driver continue alone. The admission arrangement has changed. The worker remains in the permitted safe location and contacts the designated security or sponsor channel for a valid arrangement. The original gate clearance did not authorize unsupervised movement throughout the terminal.',
 'Use a fictional terminal map with public reception, controlled route, unloading area and prohibited areas. The learner describes an arrival sequence and responds to a missing escort. Evaluate understanding of the actual access boundary and communication, without asking trainees to test or defeat real security controls. Record correct resolution as a knowledge application only.',[
 Q('Does gate admission authorize every area of a facility?','No; permission has defined boundaries.','Yes for the entire shift.','Only if wearing PPE.','Only for a delivery driver.','Local access conditions determine where the worker may go.'),
 Q('What if the required escort leaves?','Stop movement and obtain an authorized arrangement.','Continue alone by memory.','Follow an unrelated employee.','Use any open door.','A failed escort condition must be resolved before further access.'),
 Q('Does every TWIC holder automatically have escort authority?','No; the facility controls escort authorization.','Yes by card ownership.','Yes after five years.','Only at night.','Credential possession and assigned security responsibility differ.')]),
 L('Card protection, loss and suspicious use',
 'A credential is personal and should not be lent, copied for another person or left where others can use it. Protect the physical card and any associated information according to official and employer guidance. Report loss, theft, damage or suspected misuse through the current TSA and facility channels. Reporting to a supervisor alone may not complete the issuer process. A replacement request and a replacement card are different statuses; do not assume a photograph or receipt grants equivalent access. If an old card is found after being reported or replaced, confirm its status through the issuer process rather than assuming it remains usable. Local temporary access, if available, depends on the facility rules and required checks, not on a worker-made substitute.',
 'A worker loses a card and offers a phone photograph at the gate. The photograph may help explain the situation but is not automatically an acceptable replacement credential. The worker follows the loss-reporting process and asks security about permitted arrangements. A colleague offering to lend a card creates identity misuse rather than solving the access problem.',
 'Rehearse a loss report with fictional identity details, last-known location, facility contact and next steps. The evaluator checks that the learner distinguishes issuer reporting from employer notification and does not promise a specific temporary-access outcome. Use current official contact details at delivery time; do not embed stale numbers in a permanent classroom answer.',[
 Q('Can a coworker lend a TWIC to solve a lost-card problem?','No; the credential is personal.','Yes if the photograph looks similar.','Only for one shift.','Only with supervisor verbal approval.','Sharing defeats identity verification.'),
 Q('Does a photograph automatically replace the card?','No; acceptance follows the authorized facility/issuer process.','Yes everywhere.','Only in color.','Only on a company phone.','A copy is not presumed equivalent to the credential.'),
 Q('What if a reported lost card is later found?','Confirm its status through the official process before any use.','Assume it is valid forever.','Give it to another worker.','Ignore the replacement status.','Reported or replaced credentials may no longer be usable.')]),
 L('Recognize and report security concerns objectively',
 'Security reporting should describe observable behavior, location, time and immediate risk. Examples include attempted tailgating, a credential mismatch, an unattended item in an unusual location or someone seeking unauthorized access details. Appearance, nationality or accent alone is not evidence of wrongdoing. Do not confront, pursue or search people unless that is an authorized trained role; workers can maintain safe separation and notify security. Preserve useful observations without turning a report into a public accusation. An access-control worker needs post-specific training and escalation rules beyond this general awareness course. Photographs or personal details should be collected only when authorized and necessary, not as casual surveillance.',
 'At an entry point a person asks a contractor to hold the gate because they forgot a badge. The contractor does not need to determine criminal intent. The observable fact is a request to bypass verification. The contractor directs the person to the approved entry process and notifies security if needed. A useful report gives time, location and what occurred rather than speculative labels.',
 'Learners rewrite three fictional reports containing assumptions into factual observations. Then role-play a polite refusal to bypass the gate and a concise security notification. The evaluator checks calm language, objective facts and safe role boundaries. Do not stage an unauthorized penetration of a real facility as a training exercise.',[
 Q('Which fact supports a security report?','A request to bypass required verification.','A person accent alone.','A person nationality alone.','A worker clothing style alone.','Reports should concern observable behavior and access conditions.'),
 Q('Must a contractor prove malicious intent before refusing tailgating?','No; the required verification still applies.','Yes, otherwise open the gate.','Only after a confrontation.','Only if a manager witnesses it.','Following access rules does not require judging intent.'),
 Q('What is a useful report structure?','Time, place, observed behavior and immediate risk.','Rumor, accusation and guesses.','Only a name without context.','A public social-media post.','Objective details help the responsible security team assess the event.')]),
 L('Maintain access records without inventing qualifications',
 'Credential administration should capture only what is needed to verify status, validity and access decisions. Record the verification date, method and responsible person where required; do not keep unnecessary threat-assessment material in an ordinary learning file. A printed expiry date is not the only possible status issue, so follow the authorized current verification process. Project mobilization should track occupational training and maritime access separately. A worker can be fully trained for a task but awaiting access, or hold access credentials while lacking the task competence. Renewal planning should use the actual card and current issuer instructions, allowing for uncertainty without promising processing times. Completion of this VNDRLY course records understanding of those distinctions, not the issuance or renewal of a TWIC.',
 'A training matrix has one green cell labeled marine ready for a worker who passed this knowledge course. The matrix is misleading because it hides TSA credential status, facility access and occupational requirements. Replace the single inference with separate verified fields and an explicit pending condition. The resulting record supports an honest mobilization decision without storing private background data.',
 'Build a fictional mobilization checklist with separate fields for knowledge course, actual TWIC verification, facility permission, site induction and task qualification. The evaluator introduces an expired or unresolved status and asks the learner to update the decision without altering unrelated evidence. The practical desk assessment passes when the learner preserves truthful status and privacy.',[
 Q('What does completion of this course issue?','A VNDRLY maritime-access knowledge record.','A TSA TWIC.','A security clearance for every port.','A crane qualification.','The issuing agency and occupational qualifications remain separate.'),
 Q('Why separate access from task qualification in a matrix?','Either can be valid while the other is missing.','They are always identical.','It removes the need to verify status.','It guarantees approval.','Independent conditions need independent evidence.'),
 Q('What belongs in a routine training file?','Only necessary verification and learning information.','The complete threat-assessment file.','Unrelated identity documents for convenience.','Private background rumors.','Data minimization preserves privacy while supporting the actual decision.')])
]);

add('OG10','haz','This knowledge program does not represent completed HAZWOPER contact hours, supervised field days or responder qualification. Select the applicable 1910.120(e), (p) or (q) pathway and document its full training, competency, medical and practical requirements.',[
 L('Classify the operation before selecting HAZWOPER training',
 'HAZWOPER is not a universal name for any dirty or hazardous job. The regulation distinguishes covered hazardous-waste cleanup, certain treatment/storage/disposal operations, and emergency response to releases. Scope depends on the operation, not the waste drum label or the worker job title. Cleanup employees under paragraph (e), facility employees under paragraph (p), and emergency responders under paragraph (q) have different training frameworks. Ordinary incidental spill control by employees familiar with the substance can differ from emergency response, but that distinction requires credible information about quantity, toxicity, exposure potential, available equipment and capability. An unknown atmosphere or uncontrolled release cannot be made incidental by calling it housekeeping. An employer that evacuates rather than responds must have a functioning evacuation arrangement and may not quietly assign response duties to untrained workers.',
 'A facility worker finds an unknown leaking drum with a strong vapor and a nearby dizzy coworker. The worker has a general chemical-awareness course. Those facts do not support incidental cleanup. The appropriate role is to activate the emergency plan, withdraw safely and communicate observations. Later, a qualified team may classify the release and establish the response. Separately, a permitted waste-treatment facility needs its own paragraph (p) analysis rather than automatically purchasing a generic 40-hour course for every role.',
 'Give learners three fictional operations: planned contaminated-soil cleanup, normal waste-treatment work and an uncontrolled process release. Require a scope hypothesis, missing facts and the applicable paragraph to investigate. The evaluator checks that classification follows the operation and exposure, not marketing names. No learner may enter a contaminated training area as part of the paper exercise.',[
 Q('What primarily determines the HAZWOPER pathway?','The covered operation and assigned duties.','The course vendor logo.','Any presence of a drum.','The employee job title alone.','Paragraphs address distinct operational scopes.'),
 Q('Does calling an unknown vapor release housekeeping make it incidental?','No; actual hazards and capability determine the response.','Yes if the supervisor says so.','Yes below one drum.','Only at night.','A label does not change exposure risk.'),
 Q('An evacuation-only worker discovers a release. What fits the role?','Activate the plan and withdraw safely.','Approach to plug the source.','Enter to identify by smell.','Borrow a respirator and contain it.','Evacuation-only arrangements do not authorize response entry.')]),
 L('Build a site model and interpret monitoring',
 'Site characterization assembles what is known about substances, pathways and exposed people. A source-pathway-receptor model asks where contamination originates, how it moves and who or what it can reach. Airborne exposure, skin contact, ingestion from contaminated hands and physical hazards can coexist. Historical records guide sampling but do not replace present measurements. Monitoring instruments detect only their specified targets under suitable conditions. A zero reading from an unsuitable sensor is not proof of a safe atmosphere. Calibration, functional checks, location, sampling method, response time and environmental interference affect interpretation. Site characterization is updated as excavation, weather or work activity changes conditions. Measurements should have location and time so later readers can relate them to the work rather than treating a number as timeless.',
 'A soil-removal plan relies on yesterday outdoor readings. Today the crew opens a previously buried sump in still air. The source and ventilation conditions have changed; yesterday measurements cannot establish present exposure. A combustible-gas meter alone also cannot rule out every toxic vapor. The site safety team revises the sampling and control plan using the new task information before allowing the work to proceed.',
 'Draw a source-pathway-receptor diagram for a fictional sump. Identify inhalation and skin pathways, two likely physical hazards and the questions needed to select monitoring. The evaluator asks what a proposed instrument can and cannot detect and what change would trigger reassessment. Learners must resist interpreting every zero as an all-clear.',[
 Q('What can a zero reading from an unsuitable sensor establish?','Nothing reliable about an undetected substance.','That every vapor is absent.','That respirators are unnecessary.','That the site is permanently safe.','Instrument target and limitations govern interpretation.'),
 Q('Why revisit monitoring after opening a sump?','The source and exposure conditions changed.','Historical records must be destroyed.','Only paperwork changed.','Outdoor work never needs monitoring.','Characterization is updated as work reveals new hazards.'),
 Q('What links a measurement to a task?','Location, time, method and operating conditions.','Only the instrument color.','Only the worker name.','The purchase price.','Context determines whether data describe the actual exposure.')]),
 L('Control exposure with zones, equipment and decontamination',
 'Exposure control combines elimination, engineering measures, work practices and properly selected PPE. PPE selection depends on the chemical, concentration, physical form, task, contact potential and equipment limitations. A suit that resists one liquid may fail against another; chemical resistance and mechanical durability are different properties. Respirators belong within a respiratory-protection program, with appropriate selection, medical evaluation and fit testing where required. Site zones separate contaminated operations, controlled transition and clean support. They are functional boundaries, not decorative tape. Decontamination reduces transfer of contaminants to people, vehicles and clean areas. Plan the sequence, compatible cleaning methods, waste collection and emergency decontamination before entry. Heat stress, restricted vision and reduced dexterity created by protective equipment must also be managed.',
 'A worker removes dirty gloves and then touches a clean vehicle door with a contaminated sleeve. The glove change did not interrupt the whole contamination pathway. The decontamination plan needs to account for the garment exterior and the clean handoff. In another example, a chemical-resistant suit is selected only because it is available; without compatibility evidence, its appearance cannot establish protection.',
 'Use clean training garments and a harmless visual contamination marker. Trace movement from the work area through the transition zone to clean support. The evaluator observes sequencing, clean/dirty separation, assistance and waste routing. Record contamination transfer and repeat the exercise after correction. Never use actual hazardous chemicals for an introductory decontamination demonstration.',[
 Q('What does a decontamination corridor control?','Transfer from contaminated work to cleaner areas.','Only employee attendance.','The chemical composition at the source.','All medical surveillance needs.','Zone transitions are designed to interrupt contamination pathways.'),
 Q('What supports protective-suit selection?','Compatibility and task-specific performance evidence.','Color alone.','Whatever size is cheapest.','The longest shelf label.','Chemical and mechanical requirements differ among tasks.'),
 Q('Why assess heat stress in protective clothing?','The equipment can impair heat dissipation and increase workload.','It eliminates all thermal risk.','Heat matters only indoors.','Suit selection replaces breaks.','Protective equipment can introduce additional hazards.')]),
 L('Differentiate emergency response levels',
 'Awareness personnel recognize a potential release and initiate notification; they are not trained to contain it. Operations-level personnel use defensive actions from a safe distance within their training to protect people, property or the environment. Technicians are trained for more direct intervention to stop a release. Specialists provide particular hazardous-substance expertise, while incident commanders manage the response within their responsibilities. These roles are competency-based assignments, not interchangeable ranks. The response plan establishes command, communications, safe distances, control zones, medical support and decontamination. A responder who changes the tactical objective from protecting a boundary to approaching a source has changed the task and potentially the required competence. Public emergency services may need site information, but their arrival does not erase the employer responsibility to provide accurate hazard information.',
 'An operations-level responder is protecting a drainage boundary from a safe position under the plan. A coworker proposes walking through the release area to close a valve. The second action is not simply a faster version of the first: it changes location, exposure and objective. It needs the appropriate response capability and command decision. The worker communicates the valve information rather than assuming a defensive assignment authorizes source intervention.',
 'Use response cards with recognition, evacuation, distant defensive protection, source intervention and command coordination. Learners explain the differences without assuming every scenario can be resolved by a job title. The evaluator checks objectives, exposure boundaries, communication and escalation. Actual response skills require the equipment, supervision and competency evaluation appropriate to the assigned level.',[
 Q('What is the awareness-level response described here?','Recognize and notify.','Approach and plug any leak.','Enter unknown atmospheres.','Command all specialists.','Awareness recognition does not authorize containment.'),
 Q('Why is walking to the leaking valve a different assignment?','It changes exposure and moves toward source intervention.','It is always less risky.','Valve work is never response.','Distance has no effect.','Role boundaries depend on the actual task.'),
 Q('What should an arriving response team receive?','Reliable substance, location and site-hazard information.','Only the facility marketing name.','An assurance that all hazards are known.','Unverified guesses stated as facts.','Accurate site information supports safe command decisions.')]),
 L('Training hours, field experience and medical interfaces',
 'Training records must match the applicable pathway. General cleanup workers covered by 1910.120(e)(3)(i) ordinarily need 40 hours of off-site instruction and three days of supervised field experience; specified limited-task or fully characterized low-exposure pathways use different requirements. A certificate labeled 40-hour is not proof that supervised field experience occurred. Covered supervisors have additional specialized training requirements. Medical surveillance applicability depends on the regulatory criteria and assignment; confidential clinical findings should remain in the proper medical process. The operational record needs fitness and limitations relevant to work, not unnecessary diagnoses. Refresher obligations also differ: covered cleanup employees receive eight hours annually, while emergency-response provisions allow annual refresher or demonstrated competency as specified. Time and competency are separate dimensions and neither should be fabricated.',
 'A new cleanup worker has completed documented classroom instruction but no supervised field experience. The employer cannot replace three field days with three online quizzes. A qualified supervisor plans actual supervised activities and records tasks, conditions, observed performance and deficiencies. If the intended role is emergency response instead, the employer must apply the paragraph (q) competencies rather than using this cleanup example as a universal rule.',
 'Review fictional records containing course hours, attendance, supervisor identity, field tasks and medical clearance status. Identify which facts are verified, missing or irrelevant. The evaluator requires the learner to distinguish classroom hours, field experience, demonstrated competency and medical eligibility. Do not collect personal health details in the classroom exercise.',[
 Q('Do three online quizzes equal three supervised field days?','No; they are different evidence.','Yes if difficult.','Yes if timed.','Only if printed.','Field experience requires actual supervised practice.'),
 Q('Is the cleanup 40-hour pathway universal for every responder?','No; the paragraph and role determine requirements.','Yes for every job title.','Yes for every spill volume.','Only if the certificate is laminated.','Emergency-response and facility pathways have distinct provisions.'),
 Q('Which medical information belongs in routine assignment records?','Necessary work fitness or limitations, not unnecessary diagnoses.','The complete clinical history.','All family medical details.','Any rumor from coworkers.','Operational eligibility and clinical confidentiality are separate.')]),
 L('Integrated site exercise and transition to cleanup',
 'Emergency stabilization and post-emergency cleanup are distinct phases with different tasks and exposure patterns. Declaring a leak stopped does not prove contaminated equipment, soil or waste is safe to handle. The handoff needs remaining hazards, monitoring results and limitations, control zones, waste status, decontamination arrangements and the next responsible organization. Reentry decisions require evidence appropriate to the task. A training exercise should challenge changes rather than reward memorized paperwork: introduce a wind shift, failed monitor, heat-stress symptom or unexpected container. The team must reassess without losing accountability. Evaluation should record the actual decision and its basis, not simply whether the team reached the end of the script.',
 'A response team stops a release, but absorbent material remains contaminated and a sump has not been characterized. The cleanup crew receives a message saying all clear. A complete handoff would instead specify that the source is controlled, identify residual contaminated material, state measurement limitations and assign cleanup under the applicable plan. The phrase all clear conceals unresolved exposure and must be corrected before routine work resumes.',
 'Run a tabletop incident from discovery through recovery. Require a scope decision, source-pathway model, response-role assignment, zone sketch, decontamination plan and documented phase handoff. The evaluator scores evidence quality and response to a changed condition. For actual qualification, the employer supplies required practical training and field experience; this exercise supplies assessable knowledge only.',[
 Q('What does stopping a leak establish?','Source control, not automatically safe cleanup conditions.','All residue is harmless.','Every zone can disappear immediately.','No monitoring remains relevant.','Residual contamination can expose the cleanup team.'),
 Q('What should an exercise inject test?','Whether the team reassesses a meaningful change.','Whether everyone memorized the same slogan.','Whether paperwork stays unchanged.','Whether speed overrides exposure control.','Good exercises assess decisions under changing information.'),
 Q('What is a defensible recovery handoff?','Remaining hazards, evidence limits, controls and responsibility.','All clear without detail.','Only a photograph.','Only a time stamp.','The next team must understand the actual residual state.')])
]);

add('OG12','crane','These are mobile-crane knowledge lessons and synthetic calculations, not a usable lift plan or manufacturer chart. CCO examinations and applicable employer evaluation, equipment-specific instruction and supervised operation remain required.',[
 L('Select the configuration before reading capacity',
 'A mobile crane capacity is conditional on configuration. Boom length, radius, outrigger or crawler setup, counterweight, operating quadrant, reeving and attachments can change the applicable chart. Radius is the horizontal distance from the axis of rotation to the load line; it is not the distance from the bumper or nearest outrigger. A chart from a similar crane is not adequate evidence. Rated capacity may be limited by stability in one region and structural strength in another. An electronic indicator assists the operator but does not authorize exceeding the manufacturer limits or compensate for an incorrect configuration input. Before any arithmetic, verify that the chart corresponds to the actual machine and state. The load path matters because radius and quadrant can change between pickup and placement.',
 'A hypothetical chart gives 18,000 pounds at one setup and 12,000 at another. The crew selects 18,000 because it is the larger number, but the actual outrigger arrangement matches the 12,000 chart. The larger value is irrelevant. A second error measures radius from the front bumper, understating the actual distance from the rotation axis. Both errors occur before any capacity deduction and invalidate the proposed lift.',
 'Provide two deliberately different fictional chart headers and a setup sketch. Ask the learner to select the matching chart and mark radius at pickup, travel path and set-down. The evaluator requires a configuration match before calculations. For field instruction use the actual manufacturer manual and crane under a qualified instructor; the fictional numbers are never transferable to equipment.',[
 Q('Where is load radius measured from?','The crane axis of rotation to the load line horizontally.','The closest outrigger pad.','The front bumper.','The boom tip vertically.','A wrong reference understates or misstates chart radius.'),
 Q('Which chart governs?','The chart matching the actual crane and configuration.','The largest capacity in the yard.','Any chart with a similar boom.','The chart easiest to read.','Configuration is part of the capacity limit.'),
 Q('Can a capacity indicator waive chart restrictions?','No.','Yes when its screen is green.','Yes for certified operators.','Only for short lifts.','The operator must follow manufacturer limits and correct setup.')]),
 L('Gross load, deductions and utilization',
 'The load imposed on the crane includes more than the object being lifted. Hook blocks, slings, shackles, spreaders and manufacturer-specified attachments may consume rated capacity. Read the actual chart notes to determine what is included and what must be deducted; do not deduct the same item twice. For a teaching example, available payload equals stated gross capacity minus specified deductions. Utilization equals total applicable load divided by rated capacity, multiplied by 100. Utilization is a comparison, not a universal permission threshold: manufacturer restrictions, employer critical-lift criteria and changing radius still apply. Never interpolate or extrapolate a chart unless its instructions explicitly permit the method. Unknown weight is a missing input, not a quantity that can be safely guessed from appearance.',
 'A fictional matching chart allows 10,000 pounds gross. The hook block is 600, rigging 400 and a beam 1,000; the chart requires all three deductions. Available payload is 8,000 pounds. A 7,500-pound object produces 9,500 pounds total and 95% utilization. It is below this one numerical limit, but that does not establish lift approval: radius, ground, wind, path and all other conditions remain unresolved.',
 'Have learners calculate both payload and utilization, show units and identify each deduction source. Then change the rigging weight and ask them to recompute instead of retaining the old answer. The evaluator checks arithmetic and whether the learner wrongly treats a percentage as authorization. Practical chart evaluation uses an equipment-specific task set and independent checking of the actual lift inputs.',[
 Q('What is available payload in the worked case?','8,000 pounds.','10,000 pounds.','9,500 pounds.','7,500 pounds.','Subtract 600, 400 and 1,000 from 10,000.'),
 Q('What is utilization for the 7,500-pound object?','95%.','75%.','80%.','105%.','Total applicable load is 9,500 divided by 10,000.'),
 Q('Does 95% utilization alone approve the lift?','No; other applicable limits and conditions remain.','Yes universally.','Yes if the object is painted.','Only at midday.','One capacity calculation cannot establish overall lift safety.')]),
 L('Ground support and stability',
 'The ground must support the crane in its actual configuration and loading condition. Surface appearance can conceal voids, utilities, buried tanks, uncompacted fill or water-softened soil. Outrigger reaction is not simply total crane weight divided equally among four legs; reactions change with load position and geometry. Engineered bearing assessment uses the relevant reaction and suitable allowable ground pressure. As a simplified teaching relationship, pressure equals force divided by effective area. Mats distribute force only to the extent their design, placement and underlying ground support allow; a large but flexible or poorly supported mat may not develop its nominal area. Level and setup tolerances come from the manufacturer. A level crane on inadequate ground can still settle, and settlement changes the assumptions of the lift.',
 'An engineer supplies a hypothetical maximum support reaction of 80,000 pounds and an allowable bearing pressure of 2,000 pounds per square foot. The idealized minimum effective area is 40 square feet. This arithmetic does not select a mat: structural adequacy, load distribution, subsurface conditions and the engineered plan still matter. Dividing the total crane weight by four would not substitute for the supplied maximum reaction.',
 'On a site plan, identify an excavation edge, buried service, filled pit and drainage path. Compute the illustrative area and list what information is still needed. The evaluator rejects unsupported assumptions about equal reactions or full mat contact. Actual setup assessment requires the responsible qualified parties and manufacturer criteria; no ground-bearing test is improvised by trainees.',[
 Q('What idealized area follows from 80,000 lb and 2,000 lb/ft²?','40 square feet.','4 square feet.','160 square feet.','82,000 square feet.','Area equals force divided by allowable pressure.'),
 Q('Why not divide total weight equally among outriggers?','Actual reactions vary with configuration and load position.','Outriggers never carry force.','Ground pressure has no units.','All cranes have exactly equal reactions.','The critical support load needs appropriate engineering evidence.'),
 Q('Does a large mat automatically prove adequate support?','No; structural behavior and effective ground contact matter.','Yes by surface area alone.','Yes if made of wood.','Only if new.','Nominal dimensions do not establish effective distribution.')]),
 L('Rigging interfaces and load control',
 'The operator, lift director, rigger and signal person have related but distinct responsibilities. Load weight, center of gravity, attachment points and rigging arrangement determine how the load behaves. For an ideal symmetrical two-leg bridle, each leg tension is W/(2 sin θ), where θ is the leg angle above horizontal. Lower angles increase tension; the formula assumes equal sharing and does not establish sling rating or account for every connection and loading effect. Actual rigging uses manufacturer ratings, hitch reductions and competent selection. Load control should prevent people entering pinch points or standing beneath a suspended load. A tag line may help orientation when suitable, but can create snagging or entanglement hazards and is not a universal solution. A trial lift, when part of the plan, verifies behavior without replacing known weight and suitable rigging.',
 'A synthetic 4,000-pound symmetrical load uses two equally loaded legs at 30 degrees above horizontal. Each leg carries 4,000 pounds because sin 30 degrees is 0.5. At 90 degrees each would carry 2,000 pounds. The same load can therefore produce very different leg tension. If the center of gravity is offset, equal sharing is no longer a valid assumption and this simple calculation cannot size the rigging.',
 'Ask learners to draw load weight, center of gravity, leg angles and possible pinch points. Require the calculation and an explanation of its assumptions. The evaluator checks that learners do not use a teaching formula as a field selection authorization. Practical rigging demonstrations use approved training loads, verified equipment and a qualified instructor.',[
 Q('What is each leg tension in the 30-degree example?','4,000 pounds.','2,000 pounds.','1,000 pounds.','8,000 pounds.','4,000 divided by two times 0.5 is 4,000.'),
 Q('What changes when the center of gravity is offset?','Equal load sharing may no longer apply.','All legs automatically carry less.','Angles become irrelevant.','The object has no weight.','Geometry and center of gravity govern load distribution.'),
 Q('Is a tag line always safe?','No; assess snagging, entanglement and the specific load.','Yes in every lift.','Only the color matters.','It permits standing under the load.','Load-control aids have their own exposure hazards.')]),
 L('Power lines, signals and abnormal operation',
 'Electrical exposure can involve the crane, load line, rigging or load entering the power-line hazard area. Plan clearance using the applicable regulation and utility information, not an eyeballed distance or assumed voltage. Lines are treated as energized unless the specified deenergization and grounding conditions are established. A dedicated spotter and warning devices support an approved plan; they do not make contact acceptable. Signal communication must be agreed, understood and effective through the operation. Any worker can give a stop or emergency-stop signal, and the operator must respond appropriately. Lost communication, unexpected load motion, alarms, settlement or changing weather requires a controlled stop and reassessment. Restart needs the cause addressed, rather than repeated attempts against an unexplained warning.',
 'A load route approaches an overhead line. The crew has no verified voltage or approved clearance plan, but a spotter says it looks far enough away. The missing information cannot be replaced by confidence. The operation remains unstarted while the required planning is completed. During a separate simulated move, the radio fails; the operator stops rather than assuming the last command continues indefinitely.',
 'Use a site drawing and simulated radio traffic. The learner identifies electrical planning inputs, explains why a spotter is not an exemption and responds to an unexpected stop signal. The practical evaluator observes communication and controlled stopping in a safe training area. No training exercise intentionally approaches a live line or creates actual electrical contact.',[
 Q('Does a spotter eliminate required power-line planning?','No.','Yes with binoculars.','Yes if experienced.','Only below a guessed voltage.','Spotting supports controls but does not replace required clearance decisions.'),
 Q('Who may give an emergency-stop signal?','Anyone who recognizes the need.','Only the payroll supervisor.','Only the client.','Nobody except the rigger.','Stop communication must remain available when danger is recognized.'),
 Q('What follows an unexplained capacity or system warning?','A controlled stop and investigation of the cause.','Repeated overrides until movement succeeds.','Ignoring it if the load is light-looking.','Removing the display.','Warnings indicate assumptions or equipment may be wrong.')]),
 L('Inspections, practical evaluation and certification',
 'Inspection, certification and employer evaluation answer different questions. An inspection evaluates equipment condition within its scope; operator certification addresses an examination scheme; employer evaluation addresses the operator ability with equipment and assigned activities as required. None automatically proves the others. Pre-use and periodic inspection requirements need the applicable manufacturer and regulatory criteria, with defects handled through the appropriate removal-from-service or correction process. A practical assessment should use the actual relevant controls, configuration and tasks, including setup interpretation, chart use, controlled movement, signals and shutdown. The evaluator must observe performance rather than relying on years of experience alone. Training records should specify equipment/configuration, activities, date, evaluator and result so later assignments do not silently expand scope.',
 'An operator holds a current credential but has not been evaluated for the assigned crane configuration and task. The employer cannot treat the credential as the entire evaluation record. Separately, an equipment inspection finds a defect; assigning a more experienced operator does not repair it. The two issues require distinct closure: equipment disposition and operator capability evidence.',
 'Prepare a mock evaluation plan with five observable tasks and critical failure criteria: wrong chart, unsafe movement, ignored stop, unresolved defect and boundary intrusion. A qualified evaluator supplies equipment-specific tolerances and practical exercises. Record independent attempts, coaching and retests. CCO candidates follow current candidate requirements for written and practical examinations; the VNDRLY record remains its own knowledge certificate.',[
 Q('What does employer evaluation address?','Ability with the relevant equipment and assigned activities.','Only whether a certificate exists.','The crane paint condition alone.','The worker salary grade.','Certification does not replace task and equipment evaluation.'),
 Q('Can operator experience resolve an equipment defect?','No; the defect needs its appropriate disposition.','Yes after ten years.','Yes if the shift is short.','Only if the client accepts delay.','Personnel competence and equipment condition are independent controls.'),
 Q('What makes a practical record reusable within scope?','It identifies equipment, activities, evaluator, date and observed result.','It says good operator only.','It contains a generic signature.','It omits limitations.','Specific evidence prevents unsupported expansion to new assignments.')])
]);

add('OG02','rig','IADC RigPass and land/offshore endorsements require the accredited-provider route. This course assesses original drilling-orientation knowledge; employer induction, emergency drills and observed site skills remain separate.',[
 L('Rig systems, people and simultaneous operations',
 'A rig is an interacting system rather than a collection of independent jobs. Hoisting equipment moves tubulars, rotary equipment applies torque, circulating equipment moves fluid, and pressure-control equipment preserves containment. A service crew can be outside the drilling crew yet inside its hazard envelope. Draw the interfaces before work: who controls the equipment, who controls access, who accepts the work permit, and who can coordinate simultaneous activities. The driller needs immediate operational information; the installation or site manager coordinates competing work; each worker can raise a hazardous condition. A handover transfers the state of work, not just a list of names. Describe equipment left unavailable, energy sources present, barriers removed and the conditions for restart. Distinguish a routine production delay from a barrier failure: the latter changes whether work can safely continue.',
 'A mud-service technician plans a hose change while another team prepares to circulate. Both have individual work orders. The missing link is a shared equipment boundary and release condition. The coordinator identifies the common pump and discharge line, suspends the conflicting start, establishes the required isolation process, and briefs both teams. Merely telling the technician to work faster does not eliminate the interaction.',
 'Using a fictional rig layout, draw four interfaces among pumping, lifting, maintenance and vehicle delivery. For each, name the hazard source and the person who must receive a change notice. The evaluator passes the exercise only when the learner connects activities through common equipment or shared space, identifies a credible restart conflict and provides a clear handover statement.',[
 Q('Why can two individually approved work orders still conflict?','They can share equipment, energy or space.','Approval removes interactions.','Different employers cannot interact.','Only identical tasks conflict.','Work authorization must account for simultaneous operations.'),
 Q('What belongs in the pump handover?','Its isolation state and conditions for restart.','Only the next technician name.','Only completion percentage.','Only the work order date.','The receiving team needs the physical state and control conditions.'),
 Q('Which rig function primarily moves drilling fluid?','The circulating system.','The accommodation system.','The hoisting system alone.','The access-control system.','Circulation creates pressure and flow interfaces with service work.')]),
 L('Moving tubulars, rotating machinery and red zones',
 'Tubular handling combines suspended load, rotation, pinch points and changing line of fire. A pinch point exists wherever moving surfaces can trap a body part; a red zone is a controlled exposure area whose boundaries must match the operation. Visibility is not protection: an operator may be looking at the load while a helper enters behind it. Guarding separates people from rotating equipment, while exclusion and mechanized handling reduce exposure during transfers. Loose clothing and improvised hand placement increase entanglement risk. Never treat gloves as a substitute for guarding. A suspended object can swing as its center of gravity changes or a snag releases. Stored elastic energy in lines can move material beyond its previous position. Plan where people will stand through the entire movement, including landing and unhooking, rather than considering only the initial pick.',
 'A pipe initially hangs still, but one end catches a rack during travel. A helper wants to free it by hand. The correct analysis identifies a potential sudden release and a crush zone between pipe and rack. The movement is stopped and the load-handling team develops a controlled correction. The prior stillness of the load provides no evidence that the helper is safe.',
 'On a tabletop drawing, mark the swept path, landing area, pinch points and protected observation positions for a tubular move. Ask the learner to explain what changes if the load snags. During site induction the evaluator observes recognition from a protected location, not an intentional close approach to operating equipment. A pass requires identification of both movement and stored-energy exposure.',[
 Q('A snagged suspended pipe is momentarily stationary. What remains?','Potential sudden movement when the snag releases.','No hazard until visible motion returns.','Only a noise hazard.','Protection from its own weight.','A snag can store energy and redirect movement.'),
 Q('What is the strongest reason to define a swept path?','The hazard area changes throughout travel.','It replaces the lifting plan.','It permits anyone to stand under the load.','It proves the load is balanced.','People need separation along the complete movement.'),
 Q('Can gloves replace a guard on rotating machinery?','No; clothing or gloves may themselves entangle.','Yes if they are thick.','Yes for experienced workers.','Only during night shifts.','Guarding controls access to the moving hazard.')]),
 L('Pressure, trapped energy and barrier evidence',
 'Pressure produces force over area, so a small-looking closure can carry a large load. In an idealized example, force equals pressure multiplied by effective area: 1,000 psi acting over 4 square inches gives 4,000 pounds-force. This explains why loosening a fitting is not a safe pressure test. A stopped pump does not prove that check valves, accumulators, blocked sections or thermal expansion cannot retain pressure. A gauge reading is evidence from one location and one instrument; a blocked gauge port can conceal a pressurized section. Energy control requires identification of sources, suitable isolation, release or restraint of stored energy, and verification against the actual procedure. Drilling and servicing have regulatory scope distinctions; blindly applying a generic factory lockout form can miss the operational system. Workers must understand the boundary and the authorized verification method before containment is opened.',
 'A line gauge reads zero after shutdown, but a valve separates the gauge from a capped branch. Zero pressure at the gauge does not establish zero pressure behind the cap. The team identifies the segregated volume and uses the approved engineered verification method. The arithmetic for a 2-square-inch closure at 500 psi is 1,000 pounds-force; this is a consequence demonstration, not permission to test the closure manually.',
 'Have the learner annotate a simple pump/check-valve/branch diagram, locating possible trapped volumes. Require the learner to calculate the example force with units and explain why the gauge location matters. The evaluator rejects answers that propose cracking a fitting, relying on pump shutdown alone or assuming the form title proves the isolation is adequate.',[
 Q('What force does 500 psi exert over 2 square inches in this idealized case?','1,000 pounds-force.','250 pounds-force.','502 pounds-force.','2,500 pounds-force.','Multiply pressure by effective area and retain the units.'),
 Q('Why is the zero gauge insufficient in the branch case?','A valve isolates the gauge from the trapped volume.','Zero can never be measured.','All valves automatically vent.','Pressure exists only during pumping.','The evidence must describe the actual isolated volume.'),
 Q('Which action is not a verification method?','Loosening an unknown pressurized fitting.','Following an engineered isolation procedure.','Identifying trapped sections.','Confirming instrument suitability.','Opening unknown containment can release hazardous energy.')]),
 L('Land logistics, ground hazards and spill prevention',
 'Land rigs combine uneven terrain, heavy vehicles, pedestrians, pits and buried services. Separate delivery routes from walking routes and identify reversing interfaces before arrival. A spotter must occupy a protected position with a clear communication plan; losing that communication is a reason to stop the maneuver. Ground appearance does not establish bearing capacity, especially near excavations, backfilled pits and recently flooded locations. Environmental prevention begins before a transfer: identify the correct receiving vessel, available capacity, hose condition, containment and shutdown communication. Volume accounting is a useful independent check. An apparent gain or loss can signal a wrong destination, leak or measurement error and needs investigation. Spill response must match the substance and assigned response role; taking unprotected action around an unknown vapor cloud can convert a release into casualties.',
 'A tank has 1,200 gallons of verified free capacity and a delivery proposes 1,500 gallons. Even without allowing additional operating margin, the shipment exceeds available space by 300 gallons. The receiving plan must change before transfer. During the delivery, a driver also requests reversing across the pedestrian route; the crew closes and controls the crossing rather than assuming an audible alarm will protect pedestrians.',
 'Prepare a delivery sketch with pedestrian route, vehicle route, protected spotter position, receiving point and containment. Calculate the volume mismatch and identify the information needed to approve a revised transfer. The evaluator looks for independent checks of destination and capacity, positive communication, and recognition that environmental controls and traffic controls address different hazards.',[
 Q('What is the minimum capacity shortfall in the example?','300 gallons.','1,200 gallons.','2,700 gallons.','No shortfall.','1,500 minus 1,200 equals 300 before any extra margin.'),
 Q('What follows loss of spotter communication?','Stop the maneuver until communication is restored safely.','Continue at the same speed.','Assume silence means clear.','Ask pedestrians to jump aside.','The driver no longer has the agreed information for safe movement.'),
 Q('Why inspect the transfer destination?','A sound hose can still deliver to the wrong tank.','It replaces capacity checking.','It eliminates all spill risk.','Only the sender controls destination.','Correct equipment condition and correct routing are separate controls.')]),
 L('Offshore interfaces, muster and escape planning',
 'An offshore installation adds marine motion, limited escape routes, aviation interfaces and dependence on organized emergency response. Arrival induction should connect the person to alarms, muster location, accountability method, temporary refuge and assigned evacuation arrangements. Muster is a count and information process; an unreported move can prompt a needless search. Marine transfers depend on vessel and installation coordination, changing sea conditions and the specific transfer system. Helicopter passengers follow aircrew directions and aircraft-specific briefing; a rig orientation does not teach underwater escape. Weather affects lifting, access and evacuation simultaneously. The contingency plan must account for an unusable route without sending people into the hazard to recover belongings. Safety equipment familiarity means identifying the issued item and receiving actual training, not assuming similar-looking equipment works identically.',
 'An alarm occurs while a worker is between a service vessel and the accommodation area. The normal route to muster is blocked. The worker follows the installation alternative route and reports identity and location through the emergency arrangement. A colleague who leaves muster to look for the worker creates a second unknown. The lesson is to preserve command and accountability while using the planned safe alternative.',
 'Use a fictional installation plan to trace primary and alternative routes from three work locations. Have the learner explain what information a muster controller needs and why an unauthorized search creates uncertainty. For offshore deployment, an assessor conducts a physical orientation and verifies assigned safety-equipment familiarity separately. Passing the map exercise does not document a sea-survival skill.',[
 Q('Why report an alternate muster location?','Accountability depends on knowing who is safe and where.','It replaces the alarm.','It grants permission to reenter.','It cancels the emergency.','Unreported movement may trigger unnecessary search exposure.'),
 Q('Does rig orientation demonstrate underwater escape?','No; that requires appropriate supervised training.','Yes if a helicopter photograph is shown.','Yes after any land endorsement.','Only if the worker can swim.','Aircraft escape is a distinct practical competency.'),
 Q('What should happen when the primary route is unsafe?','Use the planned safe alternative and report location.','Cross the hazard to preserve the route.','Collect possessions first.','Leave the installation without reporting.','The plan must preserve both safe movement and accountability.')]),
 L('Alarm communication, incident learning and evaluated induction',
 'A useful emergency message identifies who is calling, precise location, observed condition, people affected and a safe approach or known hazard. Report observations separately from inference: a detector alarm is observed; the exact release source may be unknown. The receiver repeats critical details so a radio misunderstanding does not send help to the wrong pad. After an event, preserve evidence without delaying care or exposure control. Learning asks how equipment, planning, supervision and communication combined, rather than stopping at a label such as carelessness. An action has value when a responsible person completes it and its effect is checked. Orientation closes only when workers can locate essential controls and explain their role. A written score can identify a knowledge gap, but it cannot demonstrate correct movement through a rig or physical use of emergency equipment.',
 'Two pads share a similar name. A caller reports gas at the pump but omits the pad identifier. The dispatcher repeats the incomplete message and crews mobilize toward different locations. A corrected message includes the unique pad number, muster status, wind-dependent approach information from the site plan and the caller contact. The review addresses location labeling and radio rehearsal, not merely the caller memory.',
 'Conduct a tabletop radio drill with a deliberately ambiguous location. The learner must clarify it, communicate observed facts and obtain read-back. A site evaluator then checks recognition of muster points, alarms, protected routes and role limits. Record omissions, coaching and an unprompted repeat. Award a practical pass only for the observed induction tasks; route IADC credential requests to the accredited program.',[
 Q('What should be separated in an emergency report?','Observed facts and uncertain explanations.','Names and locations always.','All hazards from the message.','Every observation from its time.','Responders need reliable facts and clearly labeled uncertainty.'),
 Q('What makes an improvement action complete?','Implementation plus a check that the control works.','A meeting was scheduled.','A person was blamed.','A form was renamed.','An action should change the conditions that produced the event.'),
 Q('What is appropriate evidence of site orientation performance?','Observed location and role demonstrations with recorded results.','An attendance list alone.','A generic slide deck.','A different site credential.','Performance evidence must match the actual site and assigned tasks.')])
]);

add('OG06','care','This is adult workplace emergency-care knowledge. Current recognized-provider instruction, manikin/AED practice and instructor assessment are required for a first-aid/CPR/AED skills certificate. Pediatric care, medication administration and specialist rescue are outside this course.',[
 L('Recognize an emergency and activate an effective response',
 'Begin with scene safety: traffic, electricity, hazardous atmosphere and moving equipment can injure the rescuer. Do not enter a toxic atmosphere or contact an energized casualty. Once access is safe, check responsiveness and normal breathing, obtain consent when the person can respond, and activate emergency services for a life-threatening condition. An unresponsive adult with absent or abnormal breathing, including gasping, may be in cardiac arrest. Lay rescuers should not delay action with an unreliable pulse search. Put a mobile call on speaker when feasible and follow dispatcher coaching. Assign a specific person to bring the AED and another to meet responders at the access point; vague requests to a crowd often go unfulfilled. Protect yourself from blood and bodily fluids using available barriers without unnecessarily delaying lifesaving care.',
 'A contractor collapses next to a parked truck. The scene is safe, the contractor is unresponsive and only gasps occasionally. Those gasps are not reassuring normal breathing. A colleague calls emergency services on speaker and identifies the gate, another retrieves the AED, and a rescuer begins appropriate CPR. If the same collapse occurred inside an alarmed vessel, the initial action would be emergency activation and specialist rescue, not entry by the first aider.',
 'The instructor presents safe and unsafe scene cards. The learner must distinguish an accessible collapse from a hazardous rescue, identify abnormal breathing and allocate response tasks by name. Record time lost to unnecessary debate, missing location information and failure to request the AED. Use only a manikin for physical rehearsal and follow the current recognized curriculum.',[
 Q('An unresponsive adult is gasping occasionally. What does that suggest?','Possible cardiac arrest, not normal breathing.','Normal sleep.','A reason to wait ten minutes.','Proof the circulation is adequate.','Agonal gasps can occur in cardiac arrest.'),
 Q('Who should enter an alarmed confined space to retrieve a casualty?','The designated capable rescue service using its plan.','Any first aider with gloves.','The nearest coworker holding a rope.','Anyone who can hold their breath.','First aid training does not qualify hazardous-atmosphere rescue.'),
 Q('Which request best mobilizes help?','Alex, call emergency services and bring back confirmation.','Someone should probably call.','Everyone wait for management.','Call only after finding a pulse.','Specific assignments reduce diffusion of responsibility.')]),
 L('Adult CPR: quality, feedback and fatigue',
 'For adult cardiac arrest, high-quality chest compressions create blood flow while definitive help is coming. Current AHA guidance uses a rate of 100–120 compressions per minute and depth of at least 2 inches (5 cm), avoiding excessive depth above 2.4 inches (6 cm) in an average adult. Allow full recoil and minimize interruptions. A trained rescuer who can provide breaths follows the current adult 30-compressions-to-2-breaths sequence; an untrained or unwilling bystander can provide compression-only CPR for a sudden adult collapse with dispatcher assistance. This adult lesson does not transfer automatically to drowning, pediatric or professional-rescuer algorithms. Quality is a combination, not merely speed: shallow rapid compressions or leaning on the chest can be ineffective. Feedback manikins help learners identify these errors. Rescuers should coordinate changes to limit fatigue and pauses.',
 'On a manikin a learner performs 150 shallow compressions in a minute and claims that more is better. The instructor shows the rate is above the recommended range and depth is inadequate. The next trial targets 110 per minute with measured depth and full recoil. In another trial the learner reaches correct depth but pauses repeatedly to discuss performance; minimizing those interruptions becomes the specific coaching goal.',
 'Use a feedback manikin and the provider skill sheet. Observe hand position, measured rate and depth, recoil, interruptions and response to fatigue. Do not mark the skill passed from a verbal answer or a stopwatch count alone. The learner must repeat the performance successfully after feedback. Practice breaths with the appropriate barrier and equipment under the instructor curriculum.',[
 Q('What adult compression rate is taught here?','100–120 per minute.','40–60 per minute.','150–180 per minute.','As fast as physically possible.','Both speed and effective depth matter.'),
 Q('Which flaw can persist despite a correct rate?','Inadequate depth or incomplete recoil.','Correct hand position.','Minimal pauses.','Appropriate rescuer rotation.','Rate alone does not establish CPR quality.'),
 Q('What verifies the compression skill?','Observed manikin performance using the provider criteria.','Reading the rate aloud.','Signing attendance.','A course purchase receipt.','CPR is a psychomotor skill requiring observed performance.')]),
 L('AED use and coordinated resuscitation',
 'An AED analyzes heart rhythm and advises whether a shock is appropriate. It does not replace CPR or emergency activation. Turn it on, expose and prepare the chest as directed, and place pads according to the device diagrams. Follow its voice prompts. Everyone must be clear during rhythm analysis and shock delivery; touching the casualty can interfere with analysis and create shock exposure. After a shock, or when no shock is advised, resume CPR promptly as directed rather than assuming the emergency has ended. A no-shock message is a rhythm decision, not proof that circulation has returned. Device readiness matters before an emergency: accessible storage, visible signage, working status indication and in-date supplies help prevent avoidable delay. Follow device instructions for special circumstances and do not improvise pad placement or modify equipment.',
 'Two rescuers are performing CPR when the trainer AED arrives. One operates the device while the other maintains compressions until analysis is required. The operator gives a clear verbal warning and visually checks that nobody is touching the manikin. The device advises no shock; the team immediately resumes CPR. A trainee who walks away because the device did not shock has confused treatment selection with recovery.',
 'Use a trainer AED, never a live shock on a person for training. The evaluator observes pad placement, clear checks, prompt-following, coordination and rapid resumption of compressions. Introduce a no-shock scenario and an unavailable-supply scenario. Require the learner to explain both the immediate response and the readiness correction that prevents the same delay later.',[
 Q('What does no shock advised mean?','The analyzed rhythm does not call for a shock at that moment.','The person has recovered.','CPR is permanently unnecessary.','The pads should always be removed.','Continue the device-directed resuscitation sequence.'),
 Q('When must everyone be clear?','During rhythm analysis and shock delivery.','Only after emergency services arrive.','Only when the casualty speaks.','Never with modern AEDs.','Clear checks support accurate analysis and safe shock delivery.'),
 Q('What is an appropriate training device?','A trainer AED paired with a manikin.','A live shock delivered to a volunteer.','An unplugged industrial switch.','A photograph alone for skills certification.','The practical assessment requires safe realistic equipment.')]),
 L('Severe bleeding, shock and injury assessment',
 'Life-threatening bleeding needs rapid emergency activation and immediate control within training. Use a barrier and firm direct pressure at the bleeding site. For severe extremity bleeding, a trained provider may use a manufactured tourniquet according to the recognized curriculum and device instructions; improvised technique and casual removal can be dangerous. Record the application time for responders. Shock is inadequate circulation to tissues; pale or clammy skin, weakness, altered responsiveness and rapid breathing are concerning findings. Control the cause when possible, keep the casualty protected from temperature extremes and monitor breathing. Do not provide food or drink to a seriously injured person. Avoid unnecessary movement when major trauma is suspected, except when needed for immediate safety or lifesaving care. A first aider describes findings and changes rather than diagnosing internal injuries from appearance alone.',
 'A sharp edge causes heavy arm bleeding. The first aider uses gloves and direct pressure while another person calls for help. Bleeding remains severe and the trained responder applies the available approved tourniquet using the taught procedure, then records time. A coworker suggests loosening it every few minutes; the responder does not adopt that improvisation and hands management to emergency clinicians. The written exercise assesses recognition and priorities, not tourniquet skill.',
 'Use a bleeding-control trainer and the current provider lesson. Evaluate hazard recognition, barrier use, emergency activation, effective pressure, appropriate escalation and accurate handover. For tourniquet assessment use a training device and instructor-approved simulator, never tighten a device on an unsuspecting person. A learner must distinguish persistent life-threatening bleeding from a minor injury and explain the monitoring plan.',[
 Q('What is an immediate control for severe external bleeding?','Firm direct pressure with appropriate protection.','Give food and wait.','Remove all pressure repeatedly.','Apply ice as the only action.','Direct pressure is a core bleeding-control measure.'),
 Q('Which detail should accompany a tourniquet handover?','Application time and observed response.','The rescuer favorite brand only.','A promise that no other injury exists.','The victim employment status.','Responders need treatment timing and clinical observations.'),
 Q('What should the first aider report about possible shock?','Observed signs and changes without inventing a diagnosis.','That appearance rules out internal injury.','That talking rules out serious injury.','Only the injury photograph.','Trend and findings support emergency care decisions.')]),
 L('Burns, sudden illness and exposure-aware care',
 'Different causes require different scene controls. Electrical injury requires confirmation that the electrical hazard is controlled before contact. Chemical exposure requires avoiding contamination and following the substance-specific emergency information and dispatcher or medical guidance; an eyewash or shower must be reachable before work begins. For thermal burns, stop the burning process safely and use the current recognized first-aid cooling and covering instructions; do not apply grease or break blisters. Serious burns need professional assessment. Sudden chest discomfort, stroke signs, severe breathing difficulty or altered consciousness require rapid emergency activation. For suspected stroke, note when the person was last known well; that information can affect treatment. With seizures, protect from surrounding hazards, do not restrain the person and do not put objects in the mouth. Monitor breathing and follow emergency guidance.',
 'A worker suddenly has facial asymmetry and difficulty speaking. The first aider calls emergency services and learns from a witness that speech was normal at 09:10. Recording last-known-well at 09:10 is more useful than guessing that symptoms began when discovered at 09:25. In a separate splash scenario, approaching without chemical protection could contaminate the responder; the team activates the exposure plan and communicates the product information.',
 'The instructor uses illness and exposure cards. Ask the learner to identify the urgent finding, the information that changes care and the first avoidable mistake. Evaluate correct last-known-well reporting, safe handling of seizure scenarios and recognition of electrical or chemical rescue hazards. Do not practice medication administration or exposure treatment on people as part of this written course.',[
 Q('For possible stroke, which time is especially useful?','When the person was last known well.','When the next shift begins.','When the witness bought a phone.','Only the ambulance arrival time.','Last-known-well helps clinicians assess treatment options.'),
 Q('What should a first aider avoid during a seizure?','Restraint and placing objects in the mouth.','Moving nearby hazards away safely.','Calling emergency help when indicated.','Monitoring breathing afterward.','Those interventions can injure the person.'),
 Q('What comes before touching an electrical casualty?','Control of the electrical hazard.','Removing footwear from the rescuer.','Checking the casualty employer.','Pouring water on the source.','The rescuer must not become part of the electrical circuit.')]),
 L('Team drills, clinical handover and qualification route',
 'A concise handover gives the event, observed condition, important times, care provided and changes. Use plain observations such as unresponsive and gasping, not a speculative diagnosis. Include AED shocks or no-shock prompts, CPR start and bleeding-control details when known. Protect private health information from unnecessary distribution. After the event, replenish supplies, report exposure through the employer process and offer support to responders. Readiness is a system: a trained person without accessible equipment or a remote team without a reliable call route may still be unable to respond effectively. Drill the actual call, gate and location interfaces without making a false emergency dispatch. A skills certificate comes from a recognized provider after its required instruction and observed assessment. An employer separately decides staffing, coverage and site responsibilities.',
 'A site has two trained first aiders, but both are assigned to a remote area while the workshop is occupied. The coverage plan is incomplete despite two current certificates. A tabletop drill also finds the ambulance gate locked after hours. Corrective actions redistribute coverage and establish a tested access arrangement. The next drill measures whether location and access information reach the responder, not merely whether a meeting occurred.',
 'Run an adult-collapse simulation with a manikin, trainer AED, simulated dispatcher and responder handoff. Score scene safety, recognition, activation, CPR/AED performance against the provider sheet, communication and transition to incoming care. Any unsafe entry or shock-clearance failure requires correction and reassessment. Keep the provider skills record separate from the VNDRLY knowledge record and employer coverage decision.',[
 Q('Why can two current certificates still leave a coverage gap?','Both trained people may be unavailable to the occupied work area.','Certificates always guarantee coverage.','Only the certificate color matters.','Equipment locations never affect response.','Coverage must match place, time, access and staffing.'),
 Q('Which handover is most useful?','Observed condition, times, care and response to care.','Only the course score.','An unverified diagnosis only.','The complete personnel file.','Emergency clinicians need concise relevant clinical information.'),
 Q('What does this online record establish?','Assessed emergency-care knowledge, not demonstrated physical skills.','An AHA certificate automatically.','An ambulance qualification.','Universal first-aider authorization.','Recognized skills assessment and employer assignment remain separate.')])
]);
